    /// Run one headless pass over the session grid, the way
    /// `arrangement_pass` does for the timeline.
    fn session_pass(ctx: &egui::Context, arr: &mut Arrangement, events: Vec<Event>) {
        let mut out = ctx.run_ui(input(events), |ui| {
            let theme = Theme::dark();
            egui::CentralPanel::default()
                .frame(egui::Frame::new().fill(theme.bg))
                .show(ui, |ui| {
                    session_body(ui, &mut Focus::default(), &theme, arr, 4, 0.0, &[], None);
                });
        });
        out.textures_delta.clear();
    }

    /// A name longer than the box it names is CUT OFF at the edge rather
    /// than spilling across its neighbours. Clipping is a paint-level
    /// property, so this reads the tessellated output: the text shape's
    /// clip rect must not reach past the thing it labels.
    #[test]
    fn a_long_clip_name_cannot_bleed_out_of_its_clip() {
        let long = "a-really-quite-unreasonably-long-clip-name-".repeat(4);

        // In the launcher.
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        assert!(arr.create_slot_clip(0, 0, 4.0));
        arr.session.slots[0][0].as_mut().unwrap().name = long.clone();
        let mut out = ctx.run_ui(input(vec![]), |ui| {
            let theme = Theme::dark();
            egui::CentralPanel::default()
                .frame(egui::Frame::new().fill(theme.bg))
                .show(ui, |ui| {
                    session_body(
                        ui,
                        &mut Focus::default(),
                        &theme,
                        &mut arr,
                        4,
                        0.0,
                        &[],
                        None,
                    );
                });
        });
        let layout = SessionLayout::new(
            Rect::from_min_size(pos2(0.0, 0.0), SCREEN),
            arr.tracks.len(),
            arr.session.scenes.len(),
            0.0,
            0.0,
            SESSION_MIXER_H,
        );
        let slot = layout.slot(0, 0);
        let painted = out
            .shapes
            .iter()
            .filter_map(|shape| match &shape.shape {
                egui::Shape::Text(text) if text.galley.text() == long => Some(shape.clip_rect),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(painted.len(), 1, "the name is painted once");
        assert!(
            painted[0].right() <= slot.right() + 0.01,
            "the slot's name is clipped to the slot: {:?} vs {:?}",
            painted[0],
            slot
        );
        out.textures_delta.clear();

        // And on the timeline, where the clip is one grid step wide and the
        // name is a hundred times that.
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        arr.create_clip(0, 0.0, 4.0).unwrap();
        arr.clips[0][0].name = long.clone();
        let mut out = ctx.run_ui(input(vec![]), |ui| {
            let theme = Theme::dark();
            egui::CentralPanel::default()
                .frame(egui::Frame::new().fill(theme.bg))
                .show(ui, |ui| {
                    arrangement_body(
                        ui,
                        &mut Focus::default(),
                        &theme,
                        &mut arr,
                        ArrangementTransportView {
                            beats_per_bar: 4,
                            bpm: 120.0,
                            playhead: 0.0,
                            follow: false,
                        },
                        &HashMap::new(),
                        None,
                        false,
                        &ParameterRegistry::default(),
                        &mut TRACK_VOLUME_TARGET.to_owned(),
                        &mut Vec::new(),
                        &mut device::meter::Ballistics::default(),
                    );
                });
        });
        let clip_right = TL + 4.0 * PX_PER_BEAT;
        let painted = out
            .shapes
            .iter()
            .filter_map(|shape| match &shape.shape {
                egui::Shape::Text(text) if text.galley.text() == long => Some(shape.clip_rect),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(painted.len(), 1);
        assert!(
            painted[0].right() <= clip_right + 0.01,
            "the clip's name is clipped to the clip: {:?} ends past {clip_right}",
            painted[0]
        );
        out.textures_delta.clear();
    }

    /// Columns spread to fill the space they have, and stop shrinking at a
    /// width a clip name can live in — past that the grid scrolls. The
    /// scroll is clamped on construction, so no caller can hold a position
    /// that points past the end.
    #[test]
    fn the_session_grid_scrolls_once_its_columns_stop_shrinking() {
        let area = Rect::from_min_size(pos2(0.0, 0.0), vec2(600.0, 400.0));
        // The lanes stop short of BOTH pinned columns: the scenes and,
        // now, the master.
        let viewport_w = 600.0 - SCENE_COL_W - MASTER_COL_W;

        // Few tracks: everything fits, so there is nothing to scroll and no
        // scrollbar to show.
        let roomy = SessionLayout::new(area, 3, 8, 0.0, 0.0, SESSION_MIXER_H);
        assert!(roomy.column_w > SESSION_COL_MIN);
        assert_eq!(roomy.max_scroll(), 0.0);
        assert!(
            roomy.scrollbar().is_none(),
            "a bar that cannot move is not shown"
        );

        // Many tracks: the columns hold their minimum and the grid scrolls.
        let packed = SessionLayout::new(area, 20, 8, 0.0, 0.0, SESSION_MIXER_H);
        assert_eq!(packed.column_w, SESSION_COL_MIN);
        assert_eq!(packed.content_w(), 20.0 * SESSION_COL_MIN);
        assert!((packed.max_scroll() - (20.0 * SESSION_COL_MIN - viewport_w)).abs() < 0.01);
        assert!(packed.scrollbar().is_some());
        assert_eq!(
            packed.column(0).left(),
            area.left(),
            "unscrolled starts flush"
        );

        // Scrolling shifts every column left by exactly the scroll.
        let scrolled = SessionLayout::new(area, 20, 8, 100.0, 0.0, SESSION_MIXER_H);
        assert_eq!(scrolled.column(0).left(), area.left() - 100.0);
        assert_eq!(scrolled.slot(5, 2).left(), packed.slot(5, 2).left() - 100.0);

        // And it cannot run past the end, or before the start.
        let over = SessionLayout::new(area, 20, 8, 99_999.0, 0.0, SESSION_MIXER_H);
        assert_eq!(over.scroll, over.max_scroll());
        assert!(
            (over.column(19).right() - over.viewport().right()).abs() < 0.01,
            "the last column ends exactly at the scene column"
        );
        assert_eq!(
            SessionLayout::new(area, 20, 8, -50.0, 0.0, SESSION_MIXER_H).scroll,
            0.0
        );
    }

    /// The wheel scrolls the grid, and the hit tests scroll with it: a slot
    /// answers where it is DRAWN, not where it started.
    #[test]
    fn scrolling_the_grid_moves_what_a_click_hits() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        // Enough tracks that the grid is wider than the window.
        while arr.tracks.len() < 20 {
            arr.add_track(TrackKind::Midi);
        }
        assert!(arr.create_slot_clip(12, 1, 4.0));
        arr.session.selected = None;
        session_pass(&ctx, &mut arr, vec![]);
        assert_eq!(arr.session_scroll, 0.0);

        let area = Rect::from_min_size(pos2(0.0, 0.0), SCREEN);
        let unscrolled = SessionLayout::new(
            area,
            arr.tracks.len(),
            arr.session.scenes.len(),
            0.0,
            0.0,
            SESSION_MIXER_H,
        );
        assert!(unscrolled.max_scroll() > 0.0, "the grid overflows");

        // A wheel scroll over the grid moves the columns.
        let over = unscrolled.slot(0, 0).center();
        session_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(over),
                Event::MouseWheel {
                    unit: egui::MouseWheelUnit::Point,
                    delta: vec2(-200.0, 0.0),
                    phase: egui::TouchPhase::Move,
                    modifiers: Default::default(),
                },
            ],
        );
        // egui smooths a wheel over several frames, so the columns are
        // still moving here: let it settle before measuring where they
        // ended up.
        for _ in 0..30 {
            session_pass(&ctx, &mut arr, vec![]);
        }
        let scroll = arr.session_scroll;
        assert!(scroll > 0.0, "the wheel scrolled the grid");

        // Track 12's slot now sits somewhere new — and clicking it there
        // launches it, which is the whole point of the hit tests moving.
        let layout = SessionLayout::new(
            area,
            arr.tracks.len(),
            arr.session.scenes.len(),
            scroll,
            0.0,
            SESSION_MIXER_H,
        );
        let triangle = pos2(
            layout.slot(12, 1).left() + SLOT_LAUNCH_W * 0.5,
            layout.slot(12, 1).center().y,
        );
        assert!(layout.viewport().contains(triangle), "it is on screen");
        session_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(triangle),
                Event::PointerButton {
                    pos: triangle,
                    button: PointerButton::Primary,
                    pressed: true,
                    modifiers: Default::default(),
                },
                Event::PointerButton {
                    pos: triangle,
                    button: PointerButton::Primary,
                    pressed: false,
                    modifiers: Default::default(),
                },
            ],
        );
        assert_eq!(
            arr.session.playing[12],
            Some(1),
            "the scrolled slot took the click"
        );
        assert_eq!(arr.session_scroll, scroll, "and clicking did not scroll");
    }

    /// Deleting tracks until the grid fits again pulls the scroll back:
    /// a stale position is corrected the frame it is noticed.
    #[test]
    fn the_scroll_is_pulled_back_when_the_grid_shrinks() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        while arr.tracks.len() < 20 {
            arr.add_track(TrackKind::Midi);
        }
        arr.session_scroll = 400.0;
        session_pass(&ctx, &mut arr, vec![]);
        assert!(arr.session_scroll > 0.0);

        while arr.tracks.len() > 2 {
            arr.remove_track(arr.tracks.len() - 1);
        }
        session_pass(&ctx, &mut arr, vec![]);
        assert_eq!(
            arr.session_scroll, 0.0,
            "two columns fit, so there is nowhere left to scroll to"
        );
    }

    /// A PRESS MOVES THE MARKER; ONLY A STOPPED TRANSPORT FOLLOWS IT.
    ///
    /// Clicking around the arrangement while the song rolls is how you
    /// choose where to work next, and jumping the playhead to each of
    /// those made the transport follow the mouse. Stopped, the same
    /// press means "start from here", which is the whole point of an
    /// insert marker.
    ///
    /// An explicit locate — a locator, a return to start, the ruler
    /// being scrubbed — is a different intent on the same road, and it
    /// moves the playhead whatever the transport is doing.
    #[test]
    fn a_press_moves_the_playhead_only_while_stopped() {
        let seek = |playing: bool, point: Option<f32>, explicit: Option<f32>| {
            // The consumer's rule, stated the way `App::ui` applies it.
            explicit.or_else(|| point.filter(|_| !playing))
        };

        // Stopped: the press is a locate.
        assert_eq!(seek(false, Some(8.0), None), Some(8.0));
        // Rolling: it is not.
        assert_eq!(
            seek(true, Some(8.0), None),
            None,
            "a click dragged the playhead out from under a running song"
        );
        // But an explicit locate lands either way.
        assert_eq!(seek(true, None, Some(0.0)), Some(0.0));
        assert_eq!(seek(false, None, Some(0.0)), Some(0.0));
        // And an explicit locate outranks a press in the same frame:
        // pressing Home while clicking should go home.
        assert_eq!(seek(true, Some(8.0), Some(0.0)), Some(0.0));
    }

    /// A DRAG TAKES THE WHOLE SELECTION WITH IT.
    ///
    /// Dragging one clip out of a selection of six used to move that one
    /// and leave the other five behind — so a marquee could gather a
    /// phrase and then not move it, which is most of what a marquee is
    /// for. What has to survive is the SHAPE of the group: the same
    /// spacing in time, the same distance apart in lanes.
    #[test]
    fn a_group_drag_carries_the_shape_of_the_selection() {
        let mut arr = Arrangement::default();
        while arr.tracks.len() < 3 {
            arr.add_track(TrackKind::Midi);
        }
        // A phrase: two clips on lane 0, one under them on lane 1.
        let a = arr.create_clip(0, 0.0, 2.0).unwrap();
        let b = arr.create_clip(0, 4.0, 2.0).unwrap();
        let c = arr.create_clip(1, 1.0, 2.0).unwrap();
        let ids = |arr: &Arrangement, track: usize| -> Vec<(u64, f32)> {
            arr.clips[track].iter().map(|c| (c.id, c.start)).collect()
        };
        let (id_a, id_b, id_c) = (arr.clips[0][a].id, arr.clips[0][b].id, arr.clips[1][c].id);

        // Drag `a` four beats later and one lane down, with the other
        // two selected alongside it.
        let dragged = arr.clips[0][a].clone();
        let ghost = Ghost {
            track: 1,
            clip: Clip {
                start: 4.0,
                ..dragged.clone()
            },
            grab: 0.0,
            copy: false,
            fine: false,
            from_start: dragged.start,
            followers: vec![(id_b, 0), (id_c, 1)],
        };
        arr.land_ghost(ghost, 0);

        // Lane 0 is empty: everything moved down one.
        assert!(ids(&arr, 0).is_empty(), "the group left a clip behind");
        // The phrase kept its shape — four beats later, one lane down.
        let lane1 = ids(&arr, 1);
        assert_eq!(lane1.len(), 2, "lane 1 should hold `a` and `b`");
        assert_eq!(lane1[0], (id_a, 4.0));
        assert_eq!(lane1[1], (id_b, 8.0));
        assert_eq!(ids(&arr, 2), vec![(id_c, 5.0)], "`c` kept its offset");

        // AND THE GROUP IS STILL SELECTED. A move that dropped
        // everything but the clip under the pointer would make a second
        // nudge impossible without gathering the selection again.
        assert_eq!(arr.selected_clip_refs().len(), 3);
    }

    /// A COPY LEAVES THE ORIGINALS, and lands under fresh ids.
    #[test]
    fn a_group_copy_leaves_the_originals_where_they_are() {
        let mut arr = Arrangement::default();
        while arr.tracks.len() < 2 {
            arr.add_track(TrackKind::Midi);
        }
        let a = arr.create_clip(0, 0.0, 2.0).unwrap();
        let b = arr.create_clip(0, 4.0, 2.0).unwrap();
        let (id_a, id_b) = (arr.clips[0][a].id, arr.clips[0][b].id);

        let dragged = arr.clips[0][a].clone();
        arr.land_ghost(
            Ghost {
                track: 1,
                clip: Clip {
                    start: 8.0,
                    ..dragged.clone()
                },
                grab: 0.0,
                copy: true,
                fine: false,
                from_start: dragged.start,
                followers: vec![(id_b, 0)],
            },
            0,
        );

        // Both originals are untouched.
        assert_eq!(arr.clips[0].len(), 2);
        assert_eq!(arr.clips[0][0].id, id_a);
        assert_eq!(arr.clips[0][1].id, id_b);
        // And two copies landed, keeping their spacing, under ids of
        // their own — identity is never in two places.
        assert_eq!(arr.clips[1].len(), 2);
        assert_eq!(arr.clips[1][0].start, 8.0);
        assert_eq!(arr.clips[1][1].start, 12.0);
        for clip in &arr.clips[1] {
            assert!(clip.id != id_a && clip.id != id_b, "a copy reused an id");
        }
    }

    /// A group dragged against the top keeps its shape rather than
    /// losing its upper members off the end.
    #[test]
    fn a_group_dragged_off_the_top_is_clamped_not_dropped() {
        let mut arr = Arrangement::default();
        while arr.tracks.len() < 2 {
            arr.add_track(TrackKind::Midi);
        }
        let a = arr.create_clip(1, 0.0, 2.0).unwrap();
        let b = arr.create_clip(0, 0.0, 2.0).unwrap();
        let id_b = arr.clips[0][b].id;
        let dragged = arr.clips[1][a].clone();

        // Drag the lower clip up to lane 0; its follower is a lane
        // ABOVE it, which does not exist.
        arr.land_ghost(
            Ghost {
                track: 0,
                clip: dragged.clone(),
                grab: 0.0,
                copy: false,
                fine: false,
                from_start: dragged.start,
                followers: vec![(id_b, -1)],
            },
            1,
        );
        let total: usize = arr.clips.iter().map(Vec::len).sum();
        assert_eq!(total, 2, "a clip fell off the arrangement");
    }

    /// A RESIZE ENDS WHERE THE POINTER IS, wherever the clip starts.
    ///
    /// The caller handed a pointer's absolute beat to a parameter that
    /// means LENGTH, so every clip grew by its own start beat when an
    /// edge was dragged. Every existing fixture put its clip at beat
    /// zero, where the two happen to be the same number — so a whole
    /// suite passed over it.
    #[test]
    fn dragging_an_edge_ends_the_clip_under_the_pointer() {
        let grid = 1.0;
        // A clip at bar three, dragged to bar four: four bars long, not
        // seven.
        assert_eq!(drag_len(16.0, 12.0, grid), 4.0);
        // The same drag on a clip at zero — the case that hid it.
        assert_eq!(drag_len(16.0, 0.0, grid), 16.0);

        // The END lands on the grid, even from an off-grid start, so a
        // clip can always be pulled onto a bar line.
        let start = 2.5;
        for (pointer, expect_end) in [(7.4, 7.0), (7.6, 8.0), (12.2, 12.0)] {
            let end = start + drag_len(pointer, start, grid);
            assert!(
                (end - expect_end).abs() < 1e-4,
                "a drag to {pointer} ended at {end}, not {expect_end}"
            );
        }

        // A finer grid follows the pointer more closely; a coarser one
        // rounds further. Both still end where they say.
        assert_eq!(drag_len(9.3, 1.0, 0.25), 8.25);
        assert_eq!(drag_len(9.3, 1.0, 4.0), 7.0);
    }

    /// SPLIT FOLLOWS THE SELECTION, not the cursor's lane.
    ///
    /// Selecting a clip IS saying which clip you mean. Needing to also
    /// make its track current was asking the same question twice, and
    /// on the wrong answer it cut a different track — or nothing.
    #[test]
    fn split_cuts_the_selected_clips_whatever_track_is_current() {
        let mut arr = Arrangement::default();
        while arr.tracks.len() < 3 {
            arr.add_track(TrackKind::Midi);
        }
        arr.create_clip(0, 0.0, 8.0).unwrap();
        arr.create_clip(2, 0.0, 8.0).unwrap();

        // Select the clip on track 2, and leave the cursor on track 0 —
        // which is exactly the state a click on a clip leaves behind.
        arr.select_only_clip(2, 0);
        arr.cursor = Some((0, 0.0));
        arr.selection = None;

        assert!(arr.split_selection(4.0, 120.0), "nothing was cut");
        assert_eq!(arr.clips[2].len(), 2, "the selected clip was not cut");
        assert_eq!(arr.clips[2][0].len, 4.0);
        assert_eq!(arr.clips[2][1].start, 4.0);
        assert_eq!(arr.clips[0].len(), 1, "an unselected track was cut");
    }

    /// A RANGE CUTS AT BOTH EDGES, which is what isolates its middle.
    ///
    /// Cutting only at the start gave the front and everything else —
    /// never the piece the box was drawn around, which is the whole
    /// reason for drawing one.
    #[test]
    fn a_range_split_isolates_the_piece_it_covers() {
        let mut arr = Arrangement::default();
        while arr.tracks.is_empty() {
            arr.add_track(TrackKind::Midi);
        }
        arr.create_clip(0, 0.0, 8.0).unwrap();
        arr.select_only_clip(0, 0);
        arr.selection = Some((2.0, 5.0));

        assert!(arr.split_selection(0.0, 120.0));
        let spans: Vec<(f32, f32)> = arr.clips[0].iter().map(|c| (c.start, c.len)).collect();
        assert_eq!(
            spans,
            vec![(0.0, 2.0), (2.0, 3.0), (5.0, 3.0)],
            "the middle was not isolated"
        );
    }

    /// AND IT CUTS EVERY TRACK THE BAND COVERS.
    #[test]
    fn a_band_split_cuts_every_track_it_spans() {
        let mut arr = Arrangement::default();
        while arr.tracks.len() < 3 {
            arr.add_track(TrackKind::Midi);
        }
        for track in 0..3 {
            arr.create_clip(track, 0.0, 8.0).unwrap();
        }
        // A band over the first two lanes, no clips selected.
        arr.selected_clip = None;
        arr.selected_clip_ids.clear();
        arr.selected = Some(0);
        arr.selection = Some((4.0, 4.0));
        arr.selection_tracks = Some((0, 1));

        assert!(arr.split_selection(4.0, 120.0));
        assert_eq!(arr.clips[0].len(), 2);
        assert_eq!(arr.clips[1].len(), 2);
        assert_eq!(arr.clips[2].len(), 1, "a track outside the band was cut");
    }

    /// THE GRID ONLY DRAWS LINES YOU CAN TELL APART.
    ///
    /// It guarded subdivisions and then fell back to whole beats — so at
    /// eight pixels a beat it drew a line every eight pixels, and
    /// further out one every two. That is not a grid, it is a grey wash
    /// over the arrangement, and it was the loudest thing on a screen
    /// whose actual content is the clips.
    ///
    /// Ink where there is something to read, and none where there is
    /// not.
    #[test]
    fn the_grid_never_draws_lines_closer_than_it_can_resolve() {
        for ppb in [512.0f32, 256.0, 64.0, 24.0, 8.0, 4.0, 2.0, 1.0, 0.5, 0.1] {
            for sub in [0.25f32, 0.5, 1.0] {
                for per_bar in [3.0f32, 4.0, 7.0] {
                    let step = grid_step(sub, per_bar, ppb);
                    let apart = step * ppb;
                    assert!(
                        apart >= GRID_MIN_PX - 1e-3 || step >= 32.0 * per_bar,
                        "at {ppb} px/beat the grid draws every {apart} px"
                    );
                    // And it never coarsens what was already readable —
                    // a fine grid at a close zoom is still a fine grid.
                    if sub * ppb >= GRID_MIN_PX {
                        assert_eq!(step, sub, "a readable grid was thrown away");
                    }
                }
            }
        }

        // Every rung is something you could count out loud: a
        // subdivision, a beat, or a whole number of bars. A timeline
        // that gained lines at "seven beats" would be unreadable in a
        // different way.
        for ppb in [8.0f32, 4.0, 2.0, 1.0, 0.5] {
            let step = grid_step(0.25, 4.0, ppb);
            assert!(
                step == 1.0 || (step / 4.0).fract().abs() < 1e-3,
                "the grid stepped to {step} beats, which is not a musical rung"
            );
        }
    }

    /// A SELECTION SAYS HOW LONG IT IS, the way a musician counts.
    #[test]
    fn a_span_is_said_in_bars_and_beats() {
        assert_eq!(beats_as_bars(16.0, 4), "4 bars");
        assert_eq!(beats_as_bars(4.0, 4), "1 bar");
        assert_eq!(beats_as_bars(18.0, 4), "4.2");
        // Under a bar is counted in beats: "0.3" is a worse answer than
        // "3 beats" to the question being asked.
        assert_eq!(beats_as_bars(3.0, 4), "3 beats");
        assert_eq!(beats_as_bars(1.5, 4), "1.5 beats");
        // A hair under a bar line reads as the bar: the grid rounds, and
        // a selection dragged onto a bar should not say "3.4".
        assert_eq!(beats_as_bars(15.9999, 4), "4 bars");
        // Odd metres count in their own bars.
        assert_eq!(beats_as_bars(14.0, 7), "2 bars");
        // And nothing is not a crash.
        assert_eq!(beats_as_bars(0.0, 4), "0");
        assert_eq!(beats_as_bars(f32::NAN, 4), "0");
        assert_eq!(beats_as_bars(-4.0, 4), "0");
    }

    /// CUT TIME LIFTS THE SONG AND CLOSES THE GAP; PASTE TIME MAKES
    /// ROOM AND PUTS IT BACK.
    ///
    /// The pair Live has that this did not. `DeleteTime` already closed
    /// a gap and `InsertSilence` already opened one — what was missing
    /// was carrying the stretch between them, which is what makes
    /// "move this section eight bars later" one gesture instead of six.
    #[test]
    fn cut_time_and_paste_time_move_a_stretch_of_the_song() {
        let mut arr = Arrangement::default();
        while arr.tracks.len() < 2 {
            arr.add_track(TrackKind::Midi);
        }
        // Two lanes, a clip on each inside 4..8, and one after it that
        // has to ripple.
        arr.create_clip(0, 4.0, 2.0).unwrap();
        arr.create_clip(1, 6.0, 2.0).unwrap();
        arr.create_clip(0, 12.0, 2.0).unwrap();

        assert!(arr.cut_time(4.0, 8.0, 120.0));
        // The gap closed: everything after came back four beats.
        assert_eq!(arr.clips[0].len(), 1);
        assert_eq!(arr.clips[0][0].start, 8.0);
        assert!(arr.clips[1].is_empty());

        // And the stretch is being carried, its own length included —
        // the silence between the two clips is part of what was cut.
        let carried = arr.time_clipboard.clone().expect("cut took nothing");
        assert_eq!(carried.length, 4.0);
        assert_eq!(carried.clips.len(), 2);
        // Starts are relative to the cut, so it can go back anywhere.
        assert_eq!(carried.clips[0].1.start, 0.0);
        assert_eq!(carried.clips[1].1.start, 2.0);

        // Paste it at 16: room is MADE, so the clip at 8 is untouched
        // and nothing is overwritten.
        assert!(arr.paste_time(16.0, 120.0));
        assert_eq!(
            arr.clips[0][0].start, 8.0,
            "the paste overwrote earlier work"
        );
        assert_eq!(arr.clips[0][1].start, 16.0);
        assert_eq!(arr.clips[1][0].start, 18.0, "the stretch lost its shape");
        // Fresh ids: identity is never in two places.
        assert_ne!(arr.clips[0][1].id, arr.clips[0][0].id);
    }

    /// PASTE TIME PUSHES, IT DOES NOT PAINT OVER.
    ///
    /// That is the whole difference from pasting clips, and the reason
    /// the two keep separate clipboards: one is about objects and lands
    /// where you point, the other is about duration and moves whatever
    /// was already there out of its way.
    #[test]
    fn paste_time_makes_room_rather_than_overwriting() {
        let mut arr = Arrangement::default();
        while arr.tracks.is_empty() {
            arr.add_track(TrackKind::Midi);
        }
        arr.create_clip(0, 0.0, 2.0).unwrap();
        arr.cut_time(0.0, 4.0, 120.0);
        // A clip sitting exactly where the paste lands.
        arr.create_clip(0, 0.0, 2.0).unwrap();
        let sitting = arr.clips[0][0].id;

        arr.paste_time(0.0, 120.0);
        // The one that was there moved along by the pasted length.
        let moved = arr.clips[0].iter().find(|c| c.id == sitting).expect("lost");
        assert_eq!(moved.start, 4.0);
        assert_eq!(arr.clips[0].len(), 2);
    }

    /// An empty time clipboard pastes nothing, and says so rather than
    /// opening a gap of zero beats.
    #[test]
    fn pasting_time_with_nothing_carried_does_nothing() {
        let mut arr = Arrangement::default();
        while arr.tracks.is_empty() {
            arr.add_track(TrackKind::Midi);
        }
        arr.create_clip(0, 0.0, 2.0).unwrap();
        assert!(!arr.paste_time(0.0, 120.0));
        assert_eq!(arr.clips[0][0].start, 0.0);
    }

    /// A BAND LEFT OVER FROM A DRAG DOES NOT WASH LANES IT NO LONGER
    /// COVERS.
    ///
    /// Two fields that have to agree can drift, and this was how: drag a
    /// marquee three lanes deep, then arrow up. The arrow sets a
    /// one-cell selection and moves the track — and the band, if nobody
    /// forgot it, would still be washing three lanes.
    #[test]
    fn changing_track_forgets_the_band() {
        let mut arr = Arrangement::default();
        while arr.tracks.len() < 3 {
            arr.add_track(TrackKind::Midi);
        }
        arr.selection = Some((0.0, 4.0));
        arr.selection_tracks = Some((0, 2));
        assert_eq!(arr.selection_band(), Some((0, 2)));

        arr.select_track(1);
        assert_eq!(
            arr.selection_band(),
            Some((1, 1)),
            "the band outlived the gesture that drew it"
        );

        // And no selection means no band at all, however stale the
        // range is.
        arr.selection_tracks = Some((0, 2));
        arr.selection = None;
        assert_eq!(arr.selection_band(), None);
    }

    /// A BAND IS A RECTANGLE — tracks and time — and it takes every clip
    /// it touches.
    ///
    /// Touching rather than containing: Live selects a clip the marquee
    /// merely crosses, and the alternative is a band that has to be
    /// drawn exactly around a clip to take it, which on a timeline you
    /// have scrolled and zoomed is a gesture nobody lands.
    #[test]
    fn a_band_takes_every_clip_it_touches() {
        let clip = |id: u64, start: f32, len: f32| Clip {
            id,
            start,
            len,
            ..Clip::default()
        };
        // Three lanes; the middle one has two clips.
        let clips = vec![
            vec![clip(1, 0.0, 4.0)],
            vec![clip(2, 0.0, 2.0), clip(3, 8.0, 4.0)],
            vec![clip(4, 4.0, 4.0)],
        ];

        // A band over the first two lanes, beats 1..3: it crosses clip 1
        // and clip 2, and reaches neither of the others.
        assert_eq!(
            clips_in_band(&clips, (0, 1), 1.0, 3.0),
            vec![(0, 0), (1, 0)]
        );

        // Backwards is the same band — a marquee dragged up and left is
        // still a marquee.
        assert_eq!(
            clips_in_band(&clips, (1, 0), 3.0, 1.0),
            vec![(0, 0), (1, 0)]
        );

        // A band that touches only the very edge of a clip still takes
        // it: overlap is overlap.
        assert_eq!(clips_in_band(&clips, (2, 2), 7.9, 12.0), vec![(2, 0)]);
        // ...and one that stops exactly where a clip begins does not.
        assert!(clips_in_band(&clips, (2, 2), 0.0, 4.0).is_empty());

        // Every lane it spans, including ones it only passes through.
        assert_eq!(clips_in_band(&clips, (0, 2), 0.0, 16.0).len(), 4);
        // And nothing outside the lanes it names.
        assert_eq!(clips_in_band(&clips, (0, 0), 0.0, 16.0), vec![(0, 0)]);
        // A track range past the end is not a panic.
        assert!(clips_in_band(&clips, (5, 9), 0.0, 16.0).is_empty());
    }

    /// THE BAND FINDS THE LANE UNDER THE POINTER, and the nearest one
    /// when the drag has run off the ends.
    ///
    /// Nearest rather than nothing: a marquee dragged past the last lane
    /// plainly means that lane, and a `None` there would make the band
    /// collapse the moment the gesture left the track area.
    #[test]
    fn the_band_reaches_the_lane_under_the_pointer() {
        let lane = |top: f32, h: f32| {
            egui::Rect::from_min_size(egui::pos2(0.0, top), egui::vec2(100.0, h))
        };
        // The middle lane is folded away: zero height, and never the
        // answer, because it is not on screen to be dragged over.
        let lanes = [lane(0.0, 20.0), lane(20.0, 0.0), lane(20.0, 20.0)];

        assert_eq!(lane_at(&lanes, 5.0), Some(0));
        assert_eq!(lane_at(&lanes, 25.0), Some(2));
        // Past either end: the nearest real lane.
        assert_eq!(lane_at(&lanes, -100.0), Some(0));
        assert_eq!(lane_at(&lanes, 900.0), Some(2));
        // A folded lane is never chosen, even pointing straight at it.
        assert_ne!(lane_at(&lanes, 20.0), Some(1));
        // No lanes at all is the one honest `None`.
        assert_eq!(lane_at(&[], 5.0), None);
    }

    /// A click in the grid IS the insert marker: the transport moves to
    /// the snapped beat when stopped. A drag-select marks once, at the
    /// press — the selection must not scrub the song along behind it.
    /// The ruler's empty stretches scrub too.
    #[test]
    fn clicking_the_grid_moves_the_transport() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        arrangement_pass(&ctx, &mut arr, vec![]);

        // A click at beat 3.2 on lane 0 seeks to the snapped beat 3.
        let pos = pos2(TL + 3.2 * PX_PER_BEAT, LANES_TOP + TRACK_H * 0.5);
        arrangement_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(pos),
                Event::PointerButton {
                    pos,
                    button: PointerButton::Primary,
                    pressed: true,
                    modifiers: Default::default(),
                },
                Event::PointerButton {
                    pos,
                    button: PointerButton::Primary,
                    pressed: false,
                    modifiers: Default::default(),
                },
            ],
        );
        assert_eq!(arr.pending_point.take(), Some(3.0), "snapped to the grid");

        // A drag-select: one seek when the drag registers, none while the
        // selection grows. (egui reports a click on release and a drag on
        // the first movement past the threshold, so the bare press frame
        // itself sets nothing.)
        let press = pos2(TL + 4.0 * PX_PER_BEAT, LANES_TOP + TRACK_H * 0.5);
        arrangement_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(press),
                Event::PointerButton {
                    pos: press,
                    button: PointerButton::Primary,
                    pressed: true,
                    modifiers: Default::default(),
                },
            ],
        );
        assert_eq!(
            arr.pending_point, None,
            "the bare press is not yet a gesture"
        );
        arrangement_pass(
            &ctx,
            &mut arr,
            vec![Event::PointerMoved(pos2(press.x + 24.0, press.y))],
        );
        assert!(
            arr.pending_point.take().is_some(),
            "the drag's start seeks once"
        );
        for step in 2..=6 {
            let to = pos2(press.x + step as f32 * 24.0, press.y);
            arrangement_pass(&ctx, &mut arr, vec![Event::PointerMoved(to)]);
            assert_eq!(arr.pending_point, None, "the growing selection does not");
        }
        let release = pos2(press.x + 144.0, press.y);
        arrangement_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(release),
                Event::PointerButton {
                    pos: release,
                    button: PointerButton::Primary,
                    pressed: false,
                    modifiers: Default::default(),
                },
            ],
        );
        assert!(arr.selection.is_some(), "and the selection still happened");
        assert_eq!(arr.pending_point, None);

        // The ruler's empty stretch scrubs.
        let ruler = pos2(TL + 7.4 * PX_PER_BEAT, MINIMAP_H + LOOP_RULER_H * 0.5);
        arrangement_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(ruler),
                Event::PointerButton {
                    pos: ruler,
                    button: PointerButton::Primary,
                    pressed: true,
                    modifiers: Default::default(),
                },
                Event::PointerButton {
                    pos: ruler,
                    button: PointerButton::Primary,
                    pressed: false,
                    modifiers: Default::default(),
                },
            ],
        );
        // THE RULER STILL SEEKS. It is an explicit scrub, not a press
        // in the lanes — dragging the ruler is asking the playhead to
        // move, and it must do so while the song is rolling.
        assert_eq!(arr.pending_seek.take(), Some(7.0), "the ruler scrubs");
    }

    /// An LFO is a pure function of the beat — same beat, same value,
    /// every bounce — every shape stays inside ±1, and rate scales the
    /// period exactly.
    #[test]
    fn lfos_are_deterministic_functions_of_the_beat() {
        let meters = [];
        for shape in [
            ModShape::Sine,
            ModShape::Triangle,
            ModShape::Saw,
            ModShape::Square,
        ] {
            let kind = ModKind::Lfo {
                shape,
                rate_beats: 4.0,
                free: false,
                hz: 1.0,
            };
            for step in 0..64 {
                let beat = step as f32 * 0.37;
                let a = modulator_value(&kind, beat, 0.0, &meters);
                let b = modulator_value(&kind, beat, 0.0, &meters);
                assert_eq!(a, b, "{shape:?} must be a function of the beat");
                assert!((-1.0..=1.0).contains(&a), "{shape:?} out of range: {a}");
                let next_cycle = modulator_value(&kind, beat + 4.0, 0.0, &meters);
                assert!(
                    (a - next_cycle).abs() < 1e-3,
                    "{shape:?} must repeat at its rate"
                );
            }
        }
        // The shapes are the shapes.
        let sine = ModKind::Lfo {
            shape: ModShape::Sine,
            rate_beats: 4.0,
            free: false,
            hz: 1.0,
        };
        assert!(modulator_value(&sine, 0.0, 0.0, &meters).abs() < 1e-6);
        assert!((modulator_value(&sine, 1.0, 0.0, &meters) - 1.0).abs() < 1e-6);
        let square = ModKind::Lfo {
            shape: ModShape::Square,
            rate_beats: 2.0,
            free: false,
            hz: 1.0,
        };
        assert_eq!(modulator_value(&square, 0.5, 0.0, &meters), 1.0);
        assert_eq!(modulator_value(&square, 1.5, 0.0, &meters), -1.0);
    }

    /// The matrix's shape and its one-click verb: columns are exactly the
    /// applicable (track, parameter) pairs, a click wires once, and the
    /// same click can never silently double a relationship.
    #[test]
    fn the_matrix_columns_and_one_click_wire() {
        let registry = ParameterRegistry::default();
        let mut arr = Arrangement::default();
        let audio = arr.add_track(TrackKind::Audio);
        let columns = matrix_columns(&arr.tracks, &registry);
        // Deviceless tracks offer exactly volume and pan each.
        assert_eq!(columns.len(), arr.tracks.len() * 2);
        assert!(
            columns
                .iter()
                .all(|(_, target)| { target == TRACK_VOLUME_TARGET || target == TRACK_PAN_TARGET })
        );
        assert!(
            columns.iter().any(|(track, _)| *track == audio),
            "every track has its columns"
        );

        let lfo = arr.add_lfo().unwrap();
        let id = arr.add_wire(lfo, audio, TRACK_PAN_TARGET);
        assert!(id.is_some(), "one click, one wire");
        assert_eq!(
            arr.add_wire(lfo, audio, TRACK_PAN_TARGET),
            None,
            "the same click cannot double it"
        );
        assert_eq!(arr.mod_wires.len(), 1);
        assert_eq!(arr.mod_wires[0].depth, 0.25, "born at a modest depth");
        assert!(
            arr.mod_wires[0].id >= lfo,
            "wire ids come from the same mint as modulators"
        );
    }

    /// FREE mode rides the clock, not the beat: the beat can stand still
    /// and the wave still turns — and the same second gives the same value.
    #[test]
    fn free_lfos_ride_the_clock() {
        let meters = [];
        let free = ModKind::Lfo {
            shape: ModShape::Sine,
            rate_beats: 4.0,
            free: true,
            hz: 2.0,
        };
        // The beat is frozen; the clock moves the wave anyway.
        let at_zero = modulator_value(&free, 7.0, 0.0, &meters);
        let quarter = modulator_value(&free, 7.0, 0.125, &meters);
        assert!(at_zero.abs() < 1e-6);
        assert!(
            (quarter - 1.0).abs() < 1e-6,
            "2Hz peaks at 0.125s: {quarter}"
        );
        // And the clock is the whole story: any beat, same second, same value.
        assert_eq!(
            modulator_value(&free, 0.0, 3.3, &meters),
            modulator_value(&free, 99.0, 3.3, &meters),
        );
    }

    /// The wire chain: depth scales into the target's units, curve bends,
    /// steps ladder, lag glides — and bypass or standing down under a solo
    /// aims the chain at zero THROUGH the lag, so an audition is a glide.
    #[test]
    fn the_wire_chain_shapes_scales_and_glides() {
        let wire = ModWire {
            id: 1,
            source: 1,
            track: 0,
            target: aimed(7, DeviceKind::Reverb, "mix"),
            depth: 0.5,
            ..Default::default()
        };
        // A full-scale source through depth 0.5 over range 1.0 is +0.5.
        let out = wire_contribution(&wire, 1.0, 1.0, None, 0.016, false);
        assert!((out - 0.5).abs() < 1e-6, "{out}");
        // Negative depth ducks.
        let duck = ModWire {
            depth: -0.5,
            ..wire.clone()
        };
        let out = wire_contribution(&duck, 1.0, 1.0, None, 0.016, false);
        assert!((out - -0.5).abs() < 1e-6);
        // Curve 0 is the identity; a positive curve pulls the midpoint
        // down, exactly like the automation editor's bend.
        let bent = ModWire {
            curve: 0.8,
            ..wire.clone()
        };
        let straight = wire_contribution(&wire, 0.0, 1.0, None, 0.016, false);
        let curved = wire_contribution(&bent, 0.0, 1.0, None, 0.016, false);
        assert!(straight.abs() < 1e-6, "midpoint of a straight wire is zero");
        assert!(
            curved < -0.1,
            "a bent wire pulls the midpoint down: {curved}"
        );
        // Steps ladder the response: a 2-step wire knows only its ends.
        let stepped = ModWire {
            steps: 2,
            ..wire.clone()
        };
        for (source, expected) in [(-0.9, -0.5), (-0.1, -0.5), (0.1, 0.5), (0.9, 0.5)] {
            let out = wire_contribution(&stepped, source, 1.0, None, 0.016, false);
            assert!((out - expected).abs() < 1e-6, "{source} -> {out}");
        }
        // Lag approaches, never jumps — and mute glides to zero the same
        // way instead of clicking off.
        let lagged = ModWire {
            smooth_ms: 200.0,
            ..wire.clone()
        };
        let mut value = 0.0;
        for _ in 0..10 {
            value = wire_contribution(&lagged, 1.0, 1.0, Some(value), 0.016, false);
        }
        assert!(value > 0.1 && value < 0.5, "mid-glide after 160ms: {value}");
        let toward_zero = wire_contribution(&lagged, 1.0, 1.0, Some(value), 0.016, true);
        assert!(
            toward_zero < value && toward_zero > 0.0,
            "a muted wire glides down through its own lag"
        );

        // Summing several wires onto one parameter is the ENGINE's job now
        // — `wires_onto_one_parameter_sum_and_clamp_once` in
        // `audio::modulation` is where it is tested.

        // Deleting a modulator takes its wires with it.
        let mut arr = Arrangement::default();
        let lfo = arr.add_lfo().unwrap();
        arr.mod_wires.push(ModWire {
            id: 9,
            source: lfo,
            track: 0,
            target: aimed(7, DeviceKind::Reverb, "mix"),
            depth: 0.5,
            ..Default::default()
        });
        assert!(arr.remove_modulator(lfo));
        assert!(arr.mod_wires.is_empty(), "the wire went with its source");
    }

    /// The engine's tables are fixed size, so the UI must refuse rather
    /// than let the user build a source that exists on screen and drives
    /// nothing. A silent cap is worse than a full one.
    #[test]
    fn modulation_refuses_to_overfill_the_engine() {
        let mut arr = Arrangement::default();
        for i in 0..MAX_MOD_SOURCES {
            assert!(arr.add_lfo().is_some(), "source {i} should fit");
        }
        assert!(arr.add_lfo().is_none(), "one past the cap must be refused");
        assert!(arr.add_follower(0).is_none());
        assert_eq!(arr.modulators.len(), MAX_MOD_SOURCES);

        // Deleting one makes room again — the cap is a wall, not a latch.
        let first = arr.modulators[0].id;
        assert!(arr.remove_modulator(first));
        assert!(arr.add_lfo().is_some(), "room reopens after a deletion");

        // Wires have their own cap, enforced at the same door.
        arr.tracks.push(Track::default());
        let source = arr.modulators[0].id;
        arr.mod_wires = (0..MAX_MOD_WIRES as u64)
            .map(|id| ModWire {
                id: 1_000 + id,
                source,
                ..Default::default()
            })
            .collect();
        assert!(
            arr.add_wire(source, 0, TRACK_VOLUME_TARGET).is_none(),
            "a wire past the cap must be refused, not silently dropped"
        );
    }

    /// Followers listen to a LANE and wires land on one: track moves and
    /// removals carry both, and removing the listened lane removes the
    /// follower whole — with its wires.
    #[test]
    fn modulation_follows_track_surgery() {
        let mut arr = Arrangement::default();
        let follower = arr.add_follower(0).unwrap();
        arr.mod_wires.push(ModWire {
            id: 50,
            source: follower,
            track: 2,
            target: TRACK_VOLUME_TARGET.to_owned(),
            depth: 0.3,
            ..Default::default()
        });

        assert!(arr.move_track(0, 3));
        let ModKind::Follower { track } = arr.modulators[0].kind else {
            panic!("still a follower");
        };
        assert_eq!(track, 3, "the follower followed its lane");
        assert_eq!(arr.mod_wires[0].track, 1, "the wire's lane shifted up");

        assert!(arr.remove_track(1));
        assert!(
            arr.mod_wires.is_empty(),
            "the wire's lane is gone, so is it"
        );
        assert_eq!(arr.modulators.len(), 1);
        let ModKind::Follower { track } = arr.modulators[0].kind else {
            panic!("still a follower");
        };
        assert_eq!(track, 2, "the follower's lane index closed the gap");

        assert!(arr.remove_track(2), "now remove the listened lane itself");
        assert!(
            arr.modulators.is_empty(),
            "a follower of a removed lane goes with it"
        );
    }

    /// Modulation survives the project file, and a hostile file cannot
    /// smuggle a dangling wire, an orphan follower or a runaway depth in.
    #[test]
    fn modulation_round_trips_and_sanitizes() {
        let mut arr = Arrangement::default();
        let mut transport = Transport::default();
        let lfo = arr.add_lfo().unwrap();
        arr.mod_wires.push(ModWire {
            id: 51,
            source: lfo,
            track: 1,
            target: TRACK_PAN_TARGET.to_owned(),
            depth: -0.4,
            ..Default::default()
        });
        let text = ron::ser::to_string_pretty(
            &project_doc(&arr, &transport),
            ron::ser::PrettyConfig::default(),
        )
        .unwrap();
        let doc: ProjectDoc = ron::from_str(&text).unwrap();
        let mut loaded = Arrangement::default();
        apply_project_doc(doc, &mut loaded, &mut transport);
        assert_eq!(loaded.modulators, arr.modulators);
        assert_eq!(loaded.mod_wires, arr.mod_wires);
        assert!(loaded.next_modulator_id > lfo);

        // The hostile file: everything wrong at once.
        let hostile = ProjectDoc {
            tracks: vec![Track::new(TrackKind::Midi, "only".to_owned())],
            modulators: vec![
                Modulator {
                    id: 1,
                    kind: ModKind::Follower { track: 9 },
                },
                Modulator {
                    id: 2,
                    kind: ModKind::Lfo {
                        shape: ModShape::Sine,
                        rate_beats: f32::NAN,
                        free: false,
                        hz: 1.0,
                    },
                },
                Modulator {
                    id: 3,
                    kind: ModKind::Lfo {
                        shape: ModShape::Saw,
                        rate_beats: 2.0,
                        free: false,
                        hz: 1.0,
                    },
                },
            ],
            mod_wires: vec![
                ModWire {
                    id: 60,
                    source: 99,
                    track: 0,
                    target: TRACK_PAN_TARGET.to_owned(),
                    depth: 0.5,
                    ..Default::default()
                },
                ModWire {
                    id: 61,
                    source: 3,
                    track: 5,
                    target: TRACK_PAN_TARGET.to_owned(),
                    depth: 0.5,
                    ..Default::default()
                },
                ModWire {
                    id: 62,
                    source: 3,
                    track: 0,
                    target: TRACK_PAN_TARGET.to_owned(),
                    depth: 7.0,
                    ..Default::default()
                },
            ],
            next_modulator_id: 1,
            ..ProjectDoc::default()
        };
        let mut loaded = Arrangement::default();
        apply_project_doc(hostile, &mut loaded, &mut transport);
        assert_eq!(
            loaded.modulators.len(),
            1,
            "orphan follower and NaN LFO gone"
        );
        assert_eq!(
            loaded.mod_wires.len(),
            1,
            "dangling and out-of-range wires gone"
        );
        assert_eq!(loaded.mod_wires[0].depth, 1.0, "runaway depth clamped");
        assert!(loaded.next_modulator_id > 3, "the id mint repaired");
    }

    /// EVERY parameter of every device in the table resolves through the
    /// whole target machinery: it is offered, it parses back to the right
    /// instance and param id, its base reads off the device, and its range
    /// comes from the ONE params table the widget and the engine share. A
    /// device whose row exists but whose targets do not resolve is a knob
    /// that silently does nothing.
    #[test]
    fn every_device_parameter_resolves_through_the_target_machinery() {
        let registry = ParameterRegistry::default();
        // One track PER DEVICE, not one track carrying all of them: a
        // chain holds at most one instrument (`insert_device` displaces
        // any other), so two instruments on one lane would leave the first
        // unreachable and the walk would quietly stop covering it.
        let mut track = Track::new(TrackKind::Midi, "t".to_owned());
        let ids: Vec<(u64, &'static DeviceSpec, Track)> = DEVICES
            .iter()
            .enumerate()
            .map(|(at, device)| {
                let mut lane = Track::new(TrackKind::Midi, "t".to_owned());
                let id = 100 + at as u64;
                fit(&mut lane, id, device.kind);
                // The shared track still carries every EFFECT, plus the
                // last instrument, so the track-level assertions below have
                // something loaded.
                fit(&mut track, id, device.kind);
                (id, device, lane)
            })
            .collect();
        for (at, device) in DEVICES.iter().enumerate() {
            assert_eq!(
                device.params.len(),
                device.labels.len(),
                "{}'s labels do not cover its table — the registry zips them \
                 and would drop the difference silently",
                device.prefix
            );
            for other in &DEVICES[at + 1..] {
                assert_ne!(device.prefix, other.prefix, "two devices, one prefix");
            }
        }
        for (id, device, lane) in &ids {
            let offered = track_targets(lane, &registry);
            for def in device.params {
                // Every id the table declares is both readable and writable
                // on the state: a variant that forgets one drops knob edits
                // and reads a stale base, both without a word.
                let mid = def.min + (def.max - def.min) * 0.3;
                let mut state = DeviceState::new(device.kind);
                state.set(def.id, mid);
                assert_eq!(
                    state.value(def.id),
                    Some(mid),
                    "{}:{} does not survive a set",
                    device.prefix,
                    def.name
                );
                let target = device_target(*id, device, def.name);
                assert_eq!(
                    target_ref(&target),
                    Some(TargetRef::Device {
                        id: *id,
                        param: def.id
                    }),
                    "{target} does not parse back to its own device"
                );
                assert!(
                    target_applies(lane, &target),
                    "{target} should apply to the track carrying it"
                );
                assert!(
                    offered.iter().any(|entry| entry.id == target),
                    "{target} is never offered"
                );
                let spec = registry.spec(&target).expect("a registered spec");
                assert_eq!(
                    (spec.min, spec.max, spec.default),
                    (def.min, def.max, def.default),
                    "{target} restated its range instead of reading the table"
                );
                let base = parameter_base(lane, &target, spec);
                assert!(
                    (spec.min..=spec.max).contains(&base),
                    "{target}'s base {base} sits outside its own range"
                );
            }
        }
        // The track pair resolves too, and is offered whatever is loaded.
        for target in [TRACK_VOLUME_TARGET, TRACK_PAN_TARGET] {
            assert!(matches!(
                target_ref(target),
                Some(TargetRef::TrackOutput(_))
            ));
            assert!(target_applies(&track, target));
        }

        // And applicability is by INSTANCE: the same spelling against a
        // lane that does not carry that device is refused, while the track
        // pair stays.
        let bare = Track::new(TrackKind::Midi, "bare".to_owned());
        assert!(target_applies(&bare, TRACK_VOLUME_TARGET));
        for (id, device, _) in &ids {
            for def in device.params {
                assert!(!target_applies(
                    &bare,
                    &device_target(*id, device, def.name)
                ));
            }
        }
        // Junk is not a target: a garbled id, an unknown device, a
        // parameter that device does not have.
        assert_eq!(target_ref("dev.x.reverb.mix"), None);
        assert_eq!(target_ref("dev.1.chorus.mix"), None);
        // `width` used to be the example here, until the reverb grew
        // one. The point is a name the device does NOT have, so it has
        // to be a name the device does not have.
        assert_eq!(target_ref("dev.1.reverb.shimmer"), None);
        assert_eq!(target_ref("reverb.mix"), None, "v1 spellings are not v2");
    }

    /// The two directions of the card's mapping are one mapping: a stored
    /// engine value drawn as a knob position and read back must be the same
    /// number. It has to be — the rack derives the position from the stored
    /// value on every frame of a drag, so a lossy trip would walk a knob
    /// across the range while the user holds it still.
    #[test]
    fn engine_values_survive_the_trip_through_the_knobs() {
        for device in DEVICES {
            for def in device.params {
                // The ends and the inside: a mapping that only round-trips
                // at its endpoints is still broken.
                for at in [0.0f32, 0.05, 0.25, 0.5, 0.75, 0.95, 1.0] {
                    let value = def.min + (def.max - def.min) * at;
                    let there = device_norm(device.kind, def.id, value);
                    let back = device_value(device.kind, def.id, there);
                    if device_is_discrete(device.kind, def.id) {
                        // A choice SNAPS, and must not creep: the second
                        // trip has to be a no-op, or a wave selection would
                        // walk one segment along every save and reload.
                        let again = device_norm(device.kind, def.id, back);
                        assert_eq!(
                            device_value(device.kind, def.id, again),
                            back,
                            "{}:{} kept moving after it snapped",
                            device.prefix,
                            def.name
                        );
                        assert!(
                            (back - back.round()).abs() < 1e-4,
                            "{}:{} snapped to {back}, which is not a segment",
                            device.prefix,
                            def.name
                        );
                    } else {
                        assert!(
                            (back - value).abs() <= value.abs() * 1e-4 + 1e-4,
                            "{}:{} {value} -> {there} -> {back}",
                            device.prefix,
                            def.name
                        );
                    }
                    assert!(
                        (0.0..=1.0).contains(&there),
                        "{}:{} maps {value} outside the knob",
                        device.prefix,
                        def.name
                    );
                }
                // And the default, which is what a fresh device shows.
                let back = device_value(
                    device.kind,
                    def.id,
                    device_norm(device.kind, def.id, def.default),
                );
                assert!((back - def.default).abs() <= def.default.abs() * 1e-4 + 1e-4);
            }
        }
    }

    /// A project written BEFORE target ids became generic — envelopes as
    /// bare `volume`/`pan` arrays — loads into the generic model whole.
    #[test]
    fn old_automation_projects_migrate_into_envelopes() {
        let old = r#"(
            volume: [(beat: 0.0, value: 1.0, bend: 0.0), (beat: 4.0, value: 0.5, bend: 0.0)],
            pan: [(beat: 2.0, value: -1.0, bend: 0.2)],
        )"#;
        let migrated: TrackAutomation = ron::from_str(old).unwrap();
        assert_eq!(migrated.points(TRACK_VOLUME_TARGET).len(), 2);
        assert_eq!(migrated.points(TRACK_PAN_TARGET).len(), 1);
        assert_eq!(migrated.points(TRACK_PAN_TARGET)[0].bend, 0.2);

        // And the modern shape round-trips through itself unchanged.
        let mut modern = TrackAutomation::default();
        let mix = aimed(3, DeviceKind::Reverb, "mix");
        modern.insert(&mix, 0.0, 0.1);
        modern.insert(&mix, 8.0, 0.9);
        let text = ron::ser::to_string(&modern).unwrap();
        let back: TrackAutomation = ron::from_str(&text).unwrap();
        assert_eq!(back, modern);
    }

    /// The focused automation editor pans with the wheel and zooms
    /// anchored under the pointer — on the SAME view the timeline uses, so
    /// leaving focused mode lands where the curve was left.
    #[test]
    fn the_focused_automation_editor_scrolls_and_zooms() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement {
            selected: Some(0),
            ..Default::default()
        };
        let mut target = TRACK_VOLUME_TARGET.to_owned();
        let pass = |arr: &mut Arrangement, target: &mut String, events: Vec<Event>| {
            let mut out = ctx.run_ui(input(events), |ui| {
                let theme = Theme::dark();
                egui::CentralPanel::default()
                    .frame(egui::Frame::new().fill(theme.bg))
                    .show(ui, |ui| {
                        automation_editor_body(
                            ui,
                            &theme,
                            arr,
                            4,
                            &ParameterRegistry::default(),
                            target,
                        );
                    });
            });
            out.textures_delta.clear();
        };
        pass(&mut arr, &mut target, vec![]);
        assert_eq!(arr.view_beats, 0.0);

        // The wheel pans the shared view. The editor draws at twice the
        // timeline scale, so 96px of wheel is 96 / (24*2) = 2 beats.
        let over = pos2(400.0, 300.0);
        pass(
            &mut arr,
            &mut target,
            vec![
                Event::PointerMoved(over),
                Event::MouseWheel {
                    unit: egui::MouseWheelUnit::Point,
                    // The sign follows the TIMELINE's wheel, because they
                    // are the same view: positive pans later.
                    delta: vec2(96.0, 0.0),
                    phase: egui::TouchPhase::Move,
                    modifiers: Default::default(),
                },
            ],
        );
        for _ in 0..30 {
            pass(&mut arr, &mut target, vec![]);
        }
        assert!(
            (arr.view_beats - 2.0).abs() < 0.01,
            "96px at the focused scale is two beats: {}",
            arr.view_beats
        );

        // Zoom doubles the shared scale and keeps the beat under the
        // pointer under the pointer, measured at the focused scale.
        let before = arr.pixels_per_beat;
        let anchor_beat = arr.view_beats + over.x / (before * 2.0);
        pass(
            &mut arr,
            &mut target,
            vec![Event::PointerMoved(over), Event::Zoom(2.0)],
        );
        assert_eq!(arr.pixels_per_beat, before * 2.0, "the shared scale moved");
        let after_beat = arr.view_beats + over.x / (arr.pixels_per_beat * 2.0);
        assert!(
            (after_beat - anchor_beat).abs() < 0.01,
            "the anchored beat never leaves the pointer: {after_beat} vs {anchor_beat}"
        );
    }

    /// A slow Alt-drag on a curve segment accumulates its bend instead of
    /// twitching and staying flat. Regression: the bend was rebuilt each
    /// frame from `drag_delta` — the delta since the last FRAME — so every
    /// frame threw the previous frames' movement away. Same bug, same
    /// pin, as `a_slow_drag_still_moves_the_clip`.
    #[test]
    fn a_slow_alt_drag_still_bends_the_segment() {
        let ctx = egui::Context::default();
        let mut automation = TrackAutomation::default();
        automation.insert(TRACK_PAN_TARGET, 0.0, -1.0);
        automation.insert(TRACK_PAN_TARGET, 8.0, 1.0);
        let rect = Rect::from_min_size(pos2(0.0, 100.0), vec2(400.0, 100.0));
        let alt = egui::Modifiers {
            alt: true,
            ..Default::default()
        };
        let pass = |automation: &mut TrackAutomation, events: Vec<Event>| {
            let mut out = ctx.run_ui(input(events), |ui| {
                let theme = Theme::dark();
                egui::CentralPanel::default()
                    .frame(egui::Frame::new().fill(theme.bg))
                    .show(ui, |ui| {
                        automation_lane(
                            ui,
                            rect,
                            &theme,
                            0.0,
                            24.0,
                            1.0,
                            TRACK_PAN_TARGET,
                            ParameterRegistry::default().spec(TRACK_PAN_TARGET).unwrap(),
                            automation,
                            0.0,
                        );
                    });
            });
            out.textures_delta.clear();
        };
        pass(&mut automation, vec![]);

        // Press ON the segment's midpoint (beat 4 -> x 96, value 0 -> the
        // lane's vertical centre) with Alt held, then drag down in small
        // steps — each below what a single frame's delta could bend far.
        let press = pos2(96.0, 150.0);
        pass(
            &mut automation,
            vec![
                Event::ModifiersChanged(alt),
                Event::PointerMoved(press),
                Event::PointerButton {
                    pos: press,
                    button: PointerButton::Primary,
                    pressed: true,
                    modifiers: alt,
                },
            ],
        );
        for step in 1..=5 {
            let to = pos2(press.x, press.y + step as f32 * 8.0);
            pass(&mut automation, vec![Event::PointerMoved(to)]);
        }
        let release = pos2(press.x, press.y + 40.0);
        pass(
            &mut automation,
            vec![
                Event::PointerMoved(release),
                Event::PointerButton {
                    pos: release,
                    button: PointerButton::Primary,
                    pressed: false,
                    modifiers: alt,
                },
            ],
        );
        let bend = automation.points(TRACK_PAN_TARGET)[0].bend;
        assert!(
            (bend - -0.8).abs() < 0.05,
            "forty pixels of a 100px lane is a bend of -0.8, not a twitch: {bend}"
        );

        // And a fresh Alt-drag on EMPTY lane space bends nothing: the last
        // gesture's segment must not answer a drag that missed.
        let empty = pos2(320.0, 150.0);
        pass(
            &mut automation,
            vec![
                Event::PointerMoved(empty),
                Event::PointerButton {
                    pos: empty,
                    button: PointerButton::Primary,
                    pressed: true,
                    modifiers: alt,
                },
            ],
        );
        pass(
            &mut automation,
            vec![Event::PointerMoved(pos2(empty.x, empty.y + 30.0))],
        );
        pass(
            &mut automation,
            vec![
                Event::PointerButton {
                    pos: pos2(empty.x, empty.y + 30.0),
                    button: PointerButton::Primary,
                    pressed: false,
                    modifiers: alt,
                },
                Event::ModifiersChanged(Default::default()),
            ],
        );
        let after = automation.points(TRACK_PAN_TARGET)[0].bend;
        assert_eq!(after, bend, "a drag that missed the curve bends nothing");
    }

    /// The whole song survives the file: content out, RON, content back,
    /// byte-for-value equal — and what deliberately does NOT travel
    /// (playing state, selection, view) comes back fresh.
    #[test]
    fn a_project_round_trips_through_its_file() {
        let mut arr = Arrangement::default();
        let mut transport = Transport {
            bpm: 174.0,
            beats_per_bar: 3,
            metronome: true,
            loop_on: true,
            ..Default::default()
        };
        arr.tracks[1].name = "drums".to_owned();
        arr.tracks[1].mute = true;
        arr.tracks[1].pan = -0.4;
        arr.tracks[1].volume = 0.5;
        load(&mut arr, 1, DeviceKind::SineSynth);
        let audio = arr.add_track(TrackKind::Audio);
        arr.create_clip(0, 4.0, 2.0).unwrap();
        arr.clips[0][0].notes = vec![note(60, 0.5, 1.0, 90)];
        let clip_id = arr.next_id();
        arr.clips[audio].push(Clip {
            id: clip_id,
            name: "loop".to_owned(),
            start: 8.0,
            len: 4.0,
            notes: Vec::new(),
            audio: Some(AudioSource {
                transpose: 0.0,
                detune: 0.0,
                transposed_from: None,
                applied_ratio: 1.0,
                path: "/tmp/loop.wav".into(),
                sample_rate: 48_000,
                source_offset: 100,
                source_frames: 96_000,
                gain: 0.8,
                looped: true,
                file_frames: 0,
                reversed: false,
                fade_in: 0,
                fade_out: 0,
                fade_in_curve: 0.0,
                fade_out_curve: 0.0,
                envelope: Vec::new(),
            }),
            ..Clip::default()
        });
        assert!(arr.create_slot_clip(0, 2, 4.0));
        arr.session.scenes[2].name = "drop 174 bpm".to_owned();
        arr.toggle_locator(16.0, 1.0);
        arr.loop_range = Some((4.0, 12.0));
        arr.grid = 3;
        // Performance and view state, which must NOT travel.
        assert!(arr.session.launch(0, 2));
        arr.selected_clip = Some((0, 0));
        transport.playing = true;
        // A pass begins here, so the count-in is measured from where
        // the take actually started.
        transport.begin_pass();
        transport.position = 9.0;

        let text = ron::ser::to_string_pretty(
            &project_doc(&arr, &transport),
            ron::ser::PrettyConfig::default(),
        )
        .unwrap();
        let doc: ProjectDoc = ron::from_str(&text).unwrap();
        let mut loaded = Arrangement::default();
        let mut loaded_transport = Transport::default();
        apply_project_doc(doc, &mut loaded, &mut loaded_transport);

        assert_eq!(loaded.snapshot().content, arr.snapshot().content);
        assert_eq!(loaded_transport.bpm, 174.0);
        assert_eq!(loaded_transport.beats_per_bar, 3);
        assert!(loaded_transport.metronome);
        assert!(loaded_transport.loop_on);
        assert_eq!(loaded.grid, 3);
        assert!(!loaded_transport.playing, "playback does not travel");
        assert_eq!(loaded_transport.position, 0.0);
        assert!(
            loaded.session.playing.iter().all(Option::is_none),
            "nor does what was playing"
        );
        assert_eq!(loaded.selected_clip, None, "nor the selection");
        assert!(loaded.force_recompile, "and the schedule rebuilds");
    }

    /// A file is input. Mismatched parallel vecs are squared against the
    /// track list, degenerate clips are dropped, and the id counter is
    /// repaired past every id present — the identity invariant holds
    /// whatever the file said.
    #[test]
    fn a_hostile_project_file_is_sanitized() {
        let doc = ProjectDoc {
            version: 1,
            bpm: 9_999.0,
            beats_per_bar: 0,
            tracks: vec![
                Track::new(TrackKind::Midi, "a".to_owned()),
                Track::new(TrackKind::Audio, "b".to_owned()),
            ],
            // Too few clip lanes, one degenerate clip, one good one with a
            // HIGH id while the counter says 1.
            clips: vec![vec![
                Clip {
                    id: 7,
                    name: "bad".to_owned(),
                    start: -3.0,
                    len: 0.0,
                    notes: Vec::new(),
                    audio: None,
                    ..Clip::default()
                },
                Clip {
                    id: 40,
                    name: "good".to_owned(),
                    start: 0.0,
                    len: 4.0,
                    notes: Vec::new(),
                    audio: None,
                    ..Clip::default()
                },
            ]],
            // Slot columns for FIVE tracks, rows longer than the scenes.
            slots: vec![vec![None; 9]; 5],
            scenes: vec![Scene {
                name: "one".to_owned(),
            }],
            locators: vec![
                Locator {
                    beat: f32::NAN,
                    name: "nan".to_owned(),
                },
                Locator {
                    beat: 4.0,
                    name: "ok".to_owned(),
                },
            ],
            loop_range: Some((8.0, 2.0)),
            next_clip_id: 1,
            ..ProjectDoc::default()
        };
        let mut arr = Arrangement::default();
        let mut transport = Transport::default();
        apply_project_doc(doc, &mut arr, &mut transport);

        assert_eq!(arr.tracks.len(), 2);
        assert_eq!(arr.clips.len(), 2, "clip lanes squared to the tracks");
        assert_eq!(arr.clips[0].len(), 1, "the degenerate clip is gone");
        assert_eq!(arr.session.slots.len(), 2, "slot columns squared too");
        assert!(
            arr.session
                .slots
                .iter()
                .all(|column| column.len() == arr.session.scenes.len()),
            "every column matches the scenes"
        );
        assert_eq!(arr.session.playing.len(), 2);
        assert_eq!(arr.locators.len(), 1, "the NaN locator is refused");
        assert_eq!(arr.loop_range, None, "an inverted loop is no loop");
        assert!(
            arr.next_clip_id > 40,
            "the id counter is repaired past every id present"
        );
        assert!(
            (limits::BPM_MIN..=limits::BPM_MAX).contains(&transport.bpm),
            "the tempo is clamped into the app's limits"
        );
        assert!(transport.beats_per_bar >= 1);
    }

    /// The manual's three spacebars: Space restarts from the insert
    /// marker, Shift+Space resumes from the stop point, Ctrl+Space plays
    /// the selection and fences at its end.
    #[test]
    fn the_three_spacebars_mean_three_things() {
        let mut transport = Transport::default();
        let mut arr = Arrangement::default();

        // A grid click moved the marker to beat 8 (the app consumes the
        // pending seek; here the test plays that role).
        transport.marker = 8.0;
        transport.position = 123.0; // wherever playback last stopped

        // Space: starts FROM THE MARKER, not from 123 seconds.
        perform(&[UiAction::TogglePlay], &mut transport, &mut arr);
        assert!(transport.playing);
        assert_eq!(
            arr.pending_seek.take(),
            Some(8.0),
            "Space asked for the marker"
        );

        // Space again: stop. Position untouched by the verb itself.
        perform(&[UiAction::TogglePlay], &mut transport, &mut arr);
        assert!(!transport.playing);
        assert_eq!(arr.pending_seek, None, "stopping seeks nowhere");

        // Shift+Space: resume — no seek, playing from where it stands.
        perform(&[UiAction::ContinuePlay], &mut transport, &mut arr);
        assert!(transport.playing);
        assert_eq!(arr.pending_seek, None, "continue means continue");
        perform(&[UiAction::ContinuePlay], &mut transport, &mut arr);
        assert!(!transport.playing);

        // Ctrl+Space: play the selection, fenced at its end.
        arr.selection = Some((4.0, 6.0));
        perform(&[UiAction::PlaySelection], &mut transport, &mut arr);
        assert!(transport.playing);
        assert_eq!(arr.pending_seek.take(), Some(4.0));
        assert_eq!(transport.play_until, Some(6.0));

        // Any other transport verb clears the fence.
        perform(&[UiAction::TogglePlay], &mut transport, &mut arr);
        assert_eq!(transport.play_until, None, "an old fence must not ambush");

        // Without a selection, Ctrl+Space is Space.
        arr.selection = None;
        transport.marker = 2.0;
        transport.playing = false;
        perform(&[UiAction::PlaySelection], &mut transport, &mut arr);
        assert_eq!(arr.pending_seek.take(), Some(2.0));
        assert_eq!(transport.play_until, None);

        // Stop and Return bring the marker home: restarting restarts from
        // the beginning again.
        perform(&[UiAction::Stop], &mut transport, &mut arr);
        assert_eq!(transport.marker, 0.0);
        assert!(!transport.playing);
    }

    /// A click in the piano roll's ruler must move a ROLLING transport, not
    /// merely aim the next Space.
    #[test]
    fn a_locate_from_the_roll_moves_the_playhead_and_the_marker() {
        let mut transport = Transport {
            playing: true,
            position: 123.0,
            ..Transport::default()
        };
        let mut arr = Arrangement::default();

        locate_transport(7.0, 0, &mut transport, &mut arr);

        assert_eq!(
            arr.pending_seek.take(),
            Some(7.0),
            "the seek is what actually moves the engine and the mirror"
        );
        assert_eq!(transport.marker, 7.0, "and Space now starts from there");
        assert!(transport.playing, "a locate does not stop playback");
        assert_eq!(arr.cursor, Some((0, 7.0)));
        assert_eq!(arr.anchor, 7.0);

        // Same frame: a Space arriving with the click still starts from it.
        transport.playing = false;
        perform(&[UiAction::TogglePlay], &mut transport, &mut arr);
        assert_eq!(arr.pending_seek.take(), Some(7.0));
    }

    /// The keymap's Space family: shift- and ctrl-variants are listed
    /// before the plain gesture, or the plain one would swallow them.
    #[test]
    fn the_space_family_is_ordered_most_specific_first() {
        let map = daw::ui::keymap::Keymap::default();
        let pos = |action: UiAction| {
            map.bindings()
                .iter()
                .position(|b| b.action == action)
                .expect("all three spacebars are bound")
        };
        assert!(pos(UiAction::ContinuePlay) < pos(UiAction::TogglePlay));
        assert!(pos(UiAction::PlaySelection) < pos(UiAction::TogglePlay));
    }

    /// A split divides a clip in place: notes follow the beat they sound
    /// on, audio's source window advances non-destructively, and the left
    /// half keeps the identity.
    #[test]
    fn splitting_divides_notes_and_audio_windows() {
        let mut arr = Arrangement::default();
        arr.create_clip(0, 2.0, 8.0).unwrap();
        let id = arr.clips[0][0].id;
        arr.clips[0][0].notes = vec![note(60, 0.0, 1.0, 100), note(64, 5.9, 4.0, 100)];

        // Edges are not splits: nothing to divide there.
        assert!(!arr.split_at(0, 2.0, 120.0));
        assert!(!arr.split_at(0, 10.0, 120.0));
        assert!(!arr.split_at(0, 1.0, 120.0));

        assert!(arr.split_at(0, 6.0, 120.0));
        assert_eq!(arr.clips[0].len(), 2);
        let (left, right) = (&arr.clips[0][0], &arr.clips[0][1]);
        assert_eq!(left.id, id, "the left half keeps the identity");
        assert_eq!((left.start, left.len), (2.0, 4.0));
        assert_eq!((right.start, right.len), (6.0, 4.0));
        assert_eq!(left.notes.len(), 1, "the early note stays left");
        assert_eq!(right.notes.len(), 1, "the late note moved right");
        assert!(
            (right.notes[0].start - 1.9).abs() < 1e-6,
            "re-based onto the right half's start: {}",
            right.notes[0].start
        );
        assert_eq!(arr.selected_clip, Some((0, 0)));

        // Audio: the right half's source window advances by the cut. Four
        // beats at 120 bpm is two seconds — 96k frames at 48k.
        let audio = arr.add_track(TrackKind::Audio);
        arr.clips[audio].push(Clip {
            id: 999,
            name: "wav".into(),
            start: 0.0,
            len: 8.0,
            notes: Vec::new(),
            audio: Some(AudioSource {
                transpose: 0.0,
                detune: 0.0,
                transposed_from: None,
                applied_ratio: 1.0,
                path: "/tmp/x.wav".into(),
                sample_rate: 48_000,
                source_offset: 0,
                source_frames: 480_000,
                gain: 1.0,
                looped: false,
                file_frames: 0,
                reversed: false,
                fade_in: 0,
                fade_out: 0,
                fade_in_curve: 0.0,
                fade_out_curve: 0.0,
                envelope: Vec::new(),
            }),
            ..Clip::default()
        });
        assert!(arr.split_at(audio, 4.0, 120.0));
        let right = arr.clips[audio][1].audio.as_ref().unwrap();
        assert_eq!(
            right.source_offset, 96_000,
            "the window advanced by the cut"
        );
        assert_eq!(
            right.source_frames,
            480_000 - 96_000,
            "the end is invariant"
        );
        assert_eq!(arr.clips[audio][0].len, 4.0);
    }

    /// Consolidate merges the selected span's MIDI clips into one, notes
    /// re-based; audio in the span refuses the whole operation.
    /// The audio editor's selection and the arrangement's time selection
    /// are the SAME range seen from two places. If this conversion is
    /// wrong, looping a selection loops the wrong bar and playing it
    /// plays the wrong audio — and both would look right in their own
    /// region.
    #[test]
    fn an_audio_selection_maps_onto_absolute_beats() {
        let audio = AudioSource {
            transpose: 0.0,
            detune: 0.0,
            transposed_from: None,
            applied_ratio: 1.0,
            path: std::path::PathBuf::from("s.wav"),
            sample_rate: 48_000,
            source_offset: 0,
            source_frames: 96_000,
            gain: 1.0,
            looped: false,
            file_frames: 96_000,
            reversed: false,
            fade_in: 0,
            fade_out: 0,
            fade_in_curve: 0.0,
            fade_out_curve: 0.0,
            envelope: Vec::new(),
        };
        // A clip that does NOT start on a bar, so a missing `clip.start`
        // cannot pass by accident.
        let clip = Clip {
            id: 1,
            name: "s".to_owned(),
            start: 6.5,
            len: 4.0,
            notes: Vec::new(),
            audio: Some(audio.clone()),
            ..Clip::default()
        };
        let whole = waveform::Selection {
            from: 0,
            to: 96_000,
            channels: waveform::ChannelMask::all(1),
        };
        // Two seconds at 120 BPM is four beats.
        let (from, to) = selection_beats(&clip, &audio, 120.0, whole);
        assert!((from - 6.5).abs() < 1e-3, "{from}");
        assert!((to - 10.5).abs() < 1e-3, "{to}");

        // Half of it is half as many beats.
        let half = waveform::Selection {
            from: 24_000,
            to: 48_000,
            channels: waveform::ChannelMask::all(1),
        };
        let (from, to) = selection_beats(&clip, &audio, 120.0, half);
        assert!((from - 7.5).abs() < 1e-3, "{from}");
        assert!((to - 8.5).abs() < 1e-3, "{to}");

        // And the tempo is honoured: at 60 BPM the same frames are half
        // as many beats.
        let (from, to) = selection_beats(&clip, &audio, 60.0, half);
        assert!((from - 7.0).abs() < 1e-3, "{from}");
        assert!((to - 7.5).abs() < 1e-3, "{to}");

        // A clip at another rate measures in ITS frames, not the device's.
        let slow = AudioSource {
            transpose: 0.0,
            detune: 0.0,
            transposed_from: None,
            applied_ratio: 1.0,
            sample_rate: 24_000,
            ..audio.clone()
        };
        let (_, to) = selection_beats(&clip, &slow, 120.0, half);
        assert!((to - 10.5).abs() < 1e-3, "{to}");
    }

    /// REPOINTING IS THE STEP THAT CAN QUIETLY RUIN A CLIP: leave a
    /// region naming frames the new file has not got and the clip plays
    /// silence with nothing to explain it.
    #[test]
    fn repointing_a_clip_keeps_its_region_inside_the_new_file() {
        let audio = AudioSource {
            transpose: 0.0,
            detune: 0.0,
            transposed_from: None,
            applied_ratio: 1.0,
            path: std::path::PathBuf::from("old.wav"),
            sample_rate: 48_000,
            source_offset: 1_000,
            source_frames: 2_000,
            gain: 1.0,
            looped: false,
            file_frames: 10_000,
            reversed: false,
            fade_in: 0,
            fade_out: 0,
            fade_in_curve: 0.0,
            fade_out_curve: 0.0,
            envelope: Vec::new(),
        };
        let base = Clip {
            id: 1,
            name: "c".to_owned(),
            start: 0.0,
            len: 1.0,
            notes: Vec::new(),
            audio: Some(audio),
            ..Clip::default()
        };
        let rendered = |frames: u64| daw::render::Rendered {
            source: std::path::PathBuf::from("old.wav"),
            path: std::path::PathBuf::from("new.wav"),
            sample_rate: 48_000,
            channels: 1,
            frames,
        };

        // A same-length render moves nothing but the path.
        let mut clip = base.clone();
        repoint_clip(&mut clip, &rendered(10_000), None);
        let after = clip.audio.expect("audio");
        assert_eq!(after.path, std::path::PathBuf::from("new.wav"));
        assert_eq!((after.source_offset, after.source_frames), (1_000, 2_000));
        assert_eq!(after.file_frames, 10_000);

        // Material removed BEFORE the region slides it earlier.
        let mut clip = base.clone();
        repoint_clip(&mut clip, &rendered(9_500), Some((0, -500)));
        let after = clip.audio.expect("audio");
        assert_eq!((after.source_offset, after.source_frames), (500, 2_000));

        // Material removed INSIDE the region shortens it, and leaves the
        // offset where it was.
        let mut clip = base.clone();
        repoint_clip(&mut clip, &rendered(9_500), Some((1_500, -500)));
        let after = clip.audio.expect("audio");
        assert_eq!((after.source_offset, after.source_frames), (1_000, 1_500));

        // Material added AFTER the region touches neither.
        let mut clip = base.clone();
        repoint_clip(&mut clip, &rendered(10_500), Some((9_000, 500)));
        let after = clip.audio.expect("audio");
        assert_eq!((after.source_offset, after.source_frames), (1_000, 2_000));

        // AND WHATEVER THE ARITHMETIC SAID, the region fits the file. A
        // render that came back far shorter than anyone expected must
        // leave a clip that plays what is there, not one that reads past
        // the end.
        let mut clip = base;
        repoint_clip(&mut clip, &rendered(1_200), None);
        let after = clip.audio.expect("audio");
        assert_eq!(after.source_offset, 1_000);
        assert_eq!(after.source_frames, 200, "clamped to what the file has");
        assert!(after.source_offset + after.source_frames <= after.file_frames);
    }

    /// RIPPLE MOVES WORK THE USER IS NOT LOOKING AT, which is exactly why
    /// it is off by default and exactly why it needs a test.
    #[test]
    fn ripple_takes_the_clip_span_and_the_lane_with_it() {
        let clip = |id: u64, start: f32, len: f32| Clip {
            id,
            name: format!("c{id}"),
            start,
            len,
            notes: Vec::new(),
            audio: None,
            ..Clip::default()
        };
        let mut lane = vec![clip(1, 0.0, 4.0), clip(2, 4.0, 4.0), clip(3, 8.0, 4.0)];

        // A cut of one beat: the edited clip shortens, and everything
        // after it moves earlier by the same amount.
        ripple_lane(&mut lane, 0, -1.0);
        assert_eq!(lane[0].len, 3.0);
        assert_eq!(lane[1].start, 3.0);
        assert_eq!(lane[2].start, 7.0);

        // An insert lengthens and pushes later clips out.
        ripple_lane(&mut lane, 0, 2.0);
        assert_eq!(lane[0].len, 5.0);
        assert_eq!(lane[1].start, 5.0);
        assert_eq!(lane[2].start, 9.0);

        // A ripple in the middle leaves what came BEFORE alone.
        ripple_lane(&mut lane, 1, -1.0);
        assert_eq!(lane[0].start, 0.0);
        assert_eq!(lane[0].len, 5.0);
        assert_eq!(lane[1].len, 3.0);
        assert_eq!(lane[2].start, 8.0);

        // A clip cannot ripple away to nothing, and no clip is ever
        // pushed back over the one it follows.
        ripple_lane(&mut lane, 1, -999.0);
        assert!(lane[1].len > 0.0);
        assert!(lane[2].start >= lane[1].start + lane[1].len);

        // Nonsense is refused rather than propagated into every start on
        // the lane.
        let before = lane[2].start;
        ripple_lane(&mut lane, 1, f32::NAN);
        assert_eq!(lane[2].start, before);
        ripple_lane(&mut lane, 99, 1.0);
        assert_eq!(lane[2].start, before);
    }

    /// A FILE FINDS A SLOT, and only a slot that can hold it.
    ///
    /// The replacement view knows nothing about dragging files — it hands
    /// its geometry back and the app aims. This is the test that says the
    /// aiming still obeys the two rules the old view enforced: audio
    /// tracks only, and only where the grid is actually drawn.
    #[test]
    fn a_dragged_file_aims_at_audio_slots_only() {
        use daw::ui::session_next as sx;
        let view = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(900.0, 600.0));
        let state = sx::SessionViewState::default();
        let layout = sx::SessionLayout::new(view, sx::SessionShape::flat(2, 0, 8), &state);

        // Track 0 MIDI, track 1 audio.
        let midi = layout.slot(0, 0).center();
        let audio = layout.slot(1, 0).center();
        assert_eq!(layout.slot_at(midi), Some((0, 0)));
        assert_eq!(layout.slot_at(audio), Some((1, 0)));

        // Outside the rows viewport there is no slot at all — the
        // control strip and the mixer are not drop targets.
        assert_eq!(layout.slot_at(layout.control_strip().center()), None);
        assert_eq!(
            layout.slot_at(egui::pos2(view.right() + 50.0, view.center().y)),
            None
        );
    }

    /// A DEVICE NOBODY CAN LOAD DOES NOT EXIST.
    ///
    /// The browser's folders are a hand-written list beside `DEVICES`,
    /// and a second list is a list that drifts — the kick shipped with a
    /// node, a parameter table, a card and eighteen tests, and no row in
    /// the browser, so the only way to reach it was to already know it
    /// was there. Every kind has to be loadable from the tree.
    #[test]
    fn every_device_kind_is_reachable_from_the_browser() {
        let browser = Browser::default();
        let listed: Vec<DeviceKind> = tree_items(&browser.folders)
            .into_iter()
            .map(|item| item.load)
            .collect();
        let missing: Vec<&'static str> = DEVICES
            .iter()
            .filter(|spec| !listed.contains(&spec.kind))
            .map(|spec| spec.name)
            .collect();
        assert!(
            missing.is_empty(),
            "devices with no browser row — unreachable unless you already know they exist: {missing:?}"
        );

        // And the other way: no row may name a kind that is not a device.
        assert_eq!(
            listed.len(),
            DEVICES.len(),
            "the browser lists {} rows for {} devices",
            listed.len(),
            DEVICES.len()
        );

        // Instruments are filed under Instruments and effects are not —
        // the tree's one structural promise.
        for folder in &browser.folders {
            for item in folder.items {
                if folder.name == "Instruments" {
                    assert!(
                        item.load.is_instrument(),
                        "{} is not an instrument",
                        item.name
                    );
                } else if folder.name == "Audio Effects" {
                    assert!(
                        !item.load.is_instrument(),
                        "{} is an instrument, not an effect",
                        item.name
                    );
                }
            }
        }
    }

    #[test]
    fn consolidate_merges_midi_and_refuses_audio() {
        let mut arr = Arrangement::default();
        arr.create_clip(0, 0.0, 2.0).unwrap();
        arr.create_clip(0, 4.0, 2.0).unwrap();
        arr.clips[0][0].notes = vec![note(60, 0.5, 1.0, 100)];
        arr.clips[0][1].notes = vec![note(64, 0.5, 1.0, 100)];

        assert!(
            !arr.consolidate(0, 0.0, 1.0),
            "one clip is nothing to merge"
        );
        assert!(arr.consolidate(0, 0.0, 6.0));
        assert_eq!(arr.clips[0].len(), 1);
        let merged = &arr.clips[0][0];
        assert_eq!((merged.start, merged.len), (0.0, 6.0), "spans both");
        assert_eq!(merged.notes.len(), 2);
        assert!(
            (merged.notes[1].start - 4.5).abs() < 1e-9,
            "the second clip's note re-based: {}",
            merged.notes[1].start
        );

        let audio = arr.add_track(TrackKind::Audio);
        arr.clips[audio].push(Clip {
            id: 900,
            name: "a".into(),
            start: 0.0,
            len: 2.0,
            notes: Vec::new(),
            audio: Some(AudioSource {
                transpose: 0.0,
                detune: 0.0,
                transposed_from: None,
                applied_ratio: 1.0,
                path: "/tmp/x.wav".into(),
                sample_rate: 48_000,
                source_offset: 0,
                source_frames: 96_000,
                gain: 1.0,
                looped: false,
                file_frames: 0,
                reversed: false,
                fade_in: 0,
                fade_out: 0,
                fade_in_curve: 0.0,
                fade_out_curve: 0.0,
                envelope: Vec::new(),
            }),
            ..Clip::default()
        });
        let source = arr.clips[audio][0].audio.clone();
        arr.clips[audio].push(Clip {
            id: 901,
            name: "b".into(),
            start: 2.0,
            len: 2.0,
            notes: Vec::new(),
            audio: source,
            ..Clip::default()
        });
        assert!(
            !arr.consolidate(audio, 0.0, 4.0),
            "consolidating audio would be a bounce, not an edit"
        );
        assert_eq!(arr.clips[audio].len(), 2, "refused whole");
    }

    /// The time commands work on EVERY track at once: delete closes the
    /// gap, insert opens one, duplicate fills the one it opens — and clips
    /// straddling the edges are split rather than dragged along.
    #[test]
    fn time_commands_cut_across_every_track() {
        let mut arr = Arrangement::default();
        // Track 0: one clip straddling the span's left edge and reaching
        // into it. Track 1: a clip entirely after the span.
        arr.create_clip(0, 0.0, 4.0).unwrap();
        arr.create_clip(1, 8.0, 2.0).unwrap();
        arr.loop_range = Some((8.0, 12.0));
        arr.tracks[0]
            .automation
            .insert(TRACK_VOLUME_TARGET, 0.0, 0.2);
        arr.tracks[0]
            .automation
            .insert(TRACK_VOLUME_TARGET, 4.0, 0.8);
        arr.tracks[0]
            .automation
            .insert(TRACK_VOLUME_TARGET, 8.0, 1.2);

        // Delete beats 2..6: track 0's clip is cut at 2 and loses its
        // inside; track 1's clip moves 4 earlier; so does the loop.
        assert!(arr.delete_time(2.0, 6.0, 120.0));
        assert_eq!(arr.clips[0].len(), 1);
        assert_eq!(
            (arr.clips[0][0].start, arr.clips[0][0].len),
            (0.0, 2.0),
            "the straddler was split at the edge, not dragged out"
        );
        assert_eq!(arr.clips[1][0].start, 4.0, "everything after moved earlier");
        assert_eq!(arr.loop_range, Some((4.0, 8.0)), "the loop rode along");
        assert_eq!(
            arr.tracks[0]
                .automation
                .points(TRACK_VOLUME_TARGET)
                .iter()
                .map(|point| (point.beat, point.value))
                .collect::<Vec<_>>(),
            vec![(0.0, 0.2), (2.0, 1.0), (4.0, 1.2)],
            "the deleted span is replaced by the value at its far edge"
        );

        // Insert two beats at 4: the gap reopens, on every track.
        assert!(arr.insert_time(4.0, 2.0, 120.0));
        assert_eq!(arr.clips[1][0].start, 6.0);
        assert_eq!(arr.loop_range, Some((6.0, 10.0)));
        assert_eq!(
            arr.tracks[0]
                .automation
                .points(TRACK_VOLUME_TARGET)
                .iter()
                .map(|point| (point.beat, point.value))
                .collect::<Vec<_>>(),
            vec![(0.0, 0.2), (2.0, 1.0), (4.0, 1.2), (6.0, 1.2)],
            "inserting time holds the cut value through the new gap"
        );

        // Duplicate beats 0..2: a copy of track 0's clip lands at 2..4,
        // and track 1's clip moves right by the span.
        let clips_before = arr.clips[0].len();
        assert!(arr.duplicate_time(0.0, 2.0, 120.0));
        assert_eq!(arr.clips[0].len(), clips_before + 1);
        assert_eq!(arr.clips[0][1].start, 2.0, "the copy fills the opened room");
        assert_ne!(
            arr.clips[0][1].id, arr.clips[0][0].id,
            "a copy has an id of its own"
        );
        assert_eq!(arr.clips[1][0].start, 8.0);
        assert_eq!(
            arr.tracks[0]
                .automation
                .points(TRACK_VOLUME_TARGET)
                .iter()
                .map(|point| (point.beat, point.value))
                .collect::<Vec<_>>(),
            vec![(0.0, 0.2), (2.0, 0.2), (4.0, 1.0), (6.0, 1.2), (8.0, 1.2)],
            "duplicating time copies its automation phrase into the opening"
        );
        for track in &arr.clips {
            assert!(
                track.windows(2).all(|w| w[0].start <= w[1].start),
                "every track stays sorted"
            );
            for pair in track.windows(2) {
                assert!(
                    pair[0].start + pair[0].len <= pair[1].start + 1e-4,
                    "and no clips overlap"
                );
            }
        }
    }

    /// Locators toggle at a beat, and the jumps land on neighbours — with
    /// the manual's fallback to the arrangement's start.
    #[test]
    fn locators_toggle_and_jump() {
        let mut arr = Arrangement::default();
        arr.toggle_locator(8.0, 1.0);
        arr.toggle_locator(16.0, 1.0);
        assert_eq!(arr.locators.len(), 2);

        // Setting near an existing one removes it: one gesture, both verbs.
        arr.toggle_locator(8.2, 1.0);
        assert_eq!(arr.locators.len(), 1);
        assert_eq!(arr.locators[0].beat, 16.0);
        arr.toggle_locator(8.0, 1.0);

        assert_eq!(arr.locator_jump(1, 0.0), Some(8.0));
        assert_eq!(arr.locator_jump(1, 8.0), Some(16.0));
        assert_eq!(arr.locator_jump(1, 16.0), None, "nothing past the last");
        assert_eq!(arr.locator_jump(-1, 16.0), Some(8.0));
        assert_eq!(
            arr.locator_jump(-1, 4.0),
            Some(0.0),
            "before the first, the fallback is the start"
        );
        assert_eq!(arr.locator_jump(-1, 0.0), None);
    }

    /// Delete removes the most specific selection: the clip or slot when
    /// one is selected, else the TRACK — in either view.
    #[test]
    fn delete_falls_through_to_the_selected_track() {
        let mut transport = Transport::default();

        // Timeline: clip first, then the track.
        let mut arr = Arrangement::default();
        arr.create_clip(0, 0.0, 4.0).unwrap();
        arr.select_track(0);
        arr.selected_clip = Some((0, 0));
        let tracks = arr.tracks.len();
        perform(&[UiAction::DeleteSelected], &mut transport, &mut arr);
        assert!(arr.clips[0].is_empty(), "the clip went first");
        assert_eq!(arr.tracks.len(), tracks, "the track did not");
        perform(&[UiAction::DeleteSelected], &mut transport, &mut arr);
        assert_eq!(arr.tracks.len(), tracks - 1, "then the track");

        // Session: slot first, then the track.
        let mut arr = Arrangement {
            main_view: MainView::Session,
            ..Default::default()
        };
        assert!(arr.create_slot_clip(1, 0, 4.0));
        arr.select_track(1);
        let tracks = arr.tracks.len();
        perform(&[UiAction::DeleteSelected], &mut transport, &mut arr);
        assert!(arr.session.slot(1, 0).is_none(), "the slot went first");
        assert_eq!(arr.tracks.len(), tracks);
        assert_eq!(
            arr.session.selected, None,
            "clearing dropped the slot selection"
        );
        perform(&[UiAction::DeleteSelected], &mut transport, &mut arr);
        assert_eq!(arr.tracks.len(), tracks - 1, "then the track");
        assert_eq!(
            arr.session.slots.len(),
            arr.tracks.len(),
            "and the grid followed"
        );
    }

    /// The session column header renames on a double-click — the same
    /// TrackRename state the timeline header uses, so Enter and Escape
    /// mean the same thing in both views.
    #[test]
    fn the_session_header_opens_the_track_rename() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        session_pass(&ctx, &mut arr, vec![]);
        let layout = SessionLayout::new(
            Rect::from_min_size(pos2(0.0, 0.0), SCREEN),
            arr.tracks.len(),
            arr.session.scenes.len(),
            0.0,
            0.0,
            SESSION_MIXER_H,
        );
        let head = layout.head(1).center();
        for _ in 0..2 {
            session_pass(
                &ctx,
                &mut arr,
                vec![
                    Event::PointerMoved(head),
                    Event::PointerButton {
                        pos: head,
                        button: PointerButton::Primary,
                        pressed: true,
                        modifiers: Default::default(),
                    },
                    Event::PointerButton {
                        pos: head,
                        button: PointerButton::Primary,
                        pressed: false,
                        modifiers: Default::default(),
                    },
                ],
            );
        }
        assert!(
            arr.track_rename.as_ref().is_some_and(|r| r.track == 1),
            "the double-click opened the rename on the right lane"
        );
    }

    /// Dragging a session column header sideways reorders the tracks —
    /// the timeline gesture turned on its side, through the same
    /// `move_track` door, so clips, slots and playing state all follow.
    #[test]
    fn dragging_a_session_header_reorders_the_tracks() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        assert!(arr.create_slot_clip(0, 0, 4.0));
        assert!(arr.session.launch(0, 0));
        let moved = arr.tracks[0].name.clone();
        session_pass(&ctx, &mut arr, vec![]);

        let layout = SessionLayout::new(
            Rect::from_min_size(pos2(0.0, 0.0), SCREEN),
            arr.tracks.len(),
            arr.session.scenes.len(),
            0.0,
            0.0,
            SESSION_MIXER_H,
        );
        let press = layout.head(0).center();
        // Past the middle of column 2: the insertion counts two columns.
        let over = pos2(layout.column(2).center().x + 4.0, press.y);
        session_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(press),
                Event::PointerButton {
                    pos: press,
                    button: PointerButton::Primary,
                    pressed: true,
                    modifiers: Default::default(),
                },
            ],
        );
        session_pass(&ctx, &mut arr, vec![Event::PointerMoved(over)]);
        assert!(arr.track_drag.is_some(), "the drag is in flight");
        assert_eq!(arr.tracks[0].name, moved, "nothing moves until release");
        session_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(over),
                Event::PointerButton {
                    pos: over,
                    button: PointerButton::Primary,
                    pressed: false,
                    modifiers: Default::default(),
                },
            ],
        );
        assert!(arr.track_drag.is_none());
        assert_eq!(arr.tracks[2].name, moved, "the column landed at index 2");
        assert!(arr.session.slot(2, 0).is_some(), "its slot went with it");
        assert_eq!(
            arr.session.playing[2],
            Some(0),
            "and it is still playing there"
        );
    }

    /// A scene named with a tempo IS a tempo change — Ableton's classic
    /// trick — and the parser takes only what it can take safely.
    #[test]
    fn a_scene_name_can_carry_a_tempo() {
        assert_eq!(scene_tempo("verse 128 bpm"), Some(128.0));
        assert_eq!(scene_tempo("128bpm"), Some(128.0));
        assert_eq!(scene_tempo("Drop 174.5 BPM"), Some(174.5));
        assert_eq!(scene_tempo("Scene 3"), None, "a bare number is a name");
        assert_eq!(scene_tempo("bpm"), None);
        assert_eq!(
            scene_tempo("9999 bpm"),
            None,
            "outside the limits is a name"
        );
        assert_eq!(scene_tempo("10 bpm"), None);
        assert_eq!(scene_tempo(""), None);
    }

    /// Insert shifts every pointer below it; capture copies what plays
    /// under fresh ids and touches nothing audible; remove stops what it
    /// removes and the last scene stays.
    #[test]
    fn scenes_insert_capture_and_remove() {
        let mut arr = Arrangement::default();
        assert!(arr.create_slot_clip(0, 1, 4.0));
        assert!(arr.create_slot_clip(1, 3, 4.0));
        assert!(arr.session.launch(0, 1));
        assert!(arr.session.launch(1, 3));
        let before = arr.effective_clips();
        let scenes = arr.session.scenes.len();

        // Insert above the playing rows: both pointers follow their rows.
        arr.insert_scene(0);
        assert_eq!(arr.session.scenes.len(), scenes + 1);
        assert_eq!(arr.session.playing[0], Some(2), "playing followed its row");
        assert_eq!(arr.session.playing[1], Some(4));
        assert_eq!(arr.effective_clips(), before, "nothing audible moved");
        assert_eq!(
            arr.session.selected_scene,
            Some(0),
            "the new row is selected"
        );

        // Capture: a new row below the selection holding copies of what
        // plays, fresh ids, playing untouched.
        let ids: Vec<u64> = [arr.session.slot(0, 2), arr.session.slot(1, 4)]
            .iter()
            .map(|slot| slot.unwrap().id)
            .collect();
        assert!(arr.capture_scene());
        let at = arr.session.selected_scene.unwrap();
        assert_eq!(at, 1, "below the selected scene");
        let captured0 = arr.session.slot(0, at).expect("track 0 captured");
        let captured1 = arr.session.slot(1, at).expect("track 1 captured");
        assert!(!ids.contains(&captured0.id), "a copy has an id of its own");
        assert!(!ids.contains(&captured1.id));
        assert_eq!(arr.session.playing[0], Some(3), "playing did not move");
        assert_eq!(arr.effective_clips(), before, "and nothing audible changed");

        // Remove the row track 0 is playing: that track stops, loudly.
        arr.force_recompile = false;
        assert!(arr.remove_scene(3));
        assert_eq!(arr.session.playing[0], None, "its row is gone, it stops");
        assert!(arr.force_recompile, "and the engine is told now");
        assert_eq!(arr.session.playing[1], Some(4), "the other shifted down");

        // The last scene stays.
        while arr.session.scenes.len() > 1 {
            assert!(arr.remove_scene(0));
        }
        assert!(!arr.remove_scene(0), "a launcher keeps at least one row");
    }

    /// Slots move and copy between compatible lanes, replacing what they
    /// land on, with playing state following the sound.
    #[test]
    fn slots_move_between_compatible_lanes() {
        let mut arr = Arrangement::default();
        let audio = arr.add_track(TrackKind::Audio);
        assert!(arr.create_slot_clip(0, 0, 4.0));
        let id = arr.session.slot(0, 0).unwrap().id;

        // Same track: a playing clip keeps playing from its new row.
        assert!(arr.session.launch(0, 0));
        arr.force_recompile = false;
        assert!(arr.move_slot((0, 0), (0, 3), false));
        assert!(arr.session.slot(0, 0).is_none(), "the source is vacated");
        assert_eq!(
            arr.session.slot(0, 3).map(|c| c.id),
            Some(id),
            "same identity"
        );
        assert_eq!(arr.session.playing[0], Some(3), "playing followed");
        assert!(!arr.force_recompile, "nothing audible changed");

        // A MIDI clip cannot land on an audio lane.
        assert!(!arr.move_slot((0, 3), (audio, 0), false));
        assert_eq!(
            arr.session.slot(0, 3).map(|c| c.id),
            Some(id),
            "refused whole"
        );

        // A copy takes a fresh id and leaves the original.
        assert!(arr.move_slot((0, 3), (1, 0), true));
        let copy = arr.session.slot(1, 0).unwrap().id;
        assert_ne!(copy, id);
        assert!(
            arr.session.slot(0, 3).is_some(),
            "a copy leaves the original"
        );

        // Landing on a playing slot is audible: it replaces the sound.
        assert!(arr.session.launch(1, 0));
        arr.force_recompile = false;
        assert!(arr.move_slot((0, 3), (1, 0), true));
        assert!(arr.force_recompile, "replacing a playing clip is heard now");
    }

    /// The rows scroll when the scenes outgrow the space above the mixer:
    /// the wheel's vertical axis drives them, hit tests move with the
    /// paint, and a slot half under the mixer answers only for its
    /// visible part.
    #[test]
    fn the_session_rows_scroll_vertically() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        // Enough scenes that the rows overflow an 900px-tall window.
        for _ in 0..40 {
            arr.add_scene();
        }
        let last = arr.session.scenes.len() - 1;
        assert!(arr.create_slot_clip(0, last, 4.0));
        arr.session.selected = None;
        session_pass(&ctx, &mut arr, vec![]);

        let area = Rect::from_min_size(pos2(0.0, 0.0), SCREEN);
        let flat = SessionLayout::new(
            area,
            arr.tracks.len(),
            arr.session.scenes.len(),
            0.0,
            0.0,
            SESSION_MIXER_H,
        );
        assert!(flat.max_scroll_y() > 0.0, "the rows overflow");
        assert!(
            flat.slot(0, last).top() > flat.rows_viewport().bottom(),
            "the last scene starts off screen"
        );

        // Wheel down over the grid until the last row is in view.
        let over = flat.slot(0, 0).center();
        session_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(over),
                Event::MouseWheel {
                    unit: egui::MouseWheelUnit::Point,
                    delta: vec2(0.0, -4000.0),
                    phase: egui::TouchPhase::Move,
                    modifiers: Default::default(),
                },
            ],
        );
        for _ in 0..30 {
            session_pass(&ctx, &mut arr, vec![]);
        }
        assert_eq!(
            arr.session_scroll_y,
            flat.max_scroll_y(),
            "a big wheel lands at the bottom, clamped"
        );
        assert_eq!(arr.session_scroll, 0.0, "and the columns did not move");

        // The last scene's slot is now on screen, and clicking its
        // triangle launches it — the hit test scrolled with the paint.
        let scrolled = SessionLayout::new(
            area,
            arr.tracks.len(),
            arr.session.scenes.len(),
            0.0,
            arr.session_scroll_y,
            SESSION_MIXER_H,
        );
        let slot = scrolled.slot(0, last);
        assert!(scrolled.rows_viewport().contains(slot.center()));
        let triangle = pos2(slot.left() + SLOT_LAUNCH_W * 0.5, slot.center().y);
        session_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(triangle),
                Event::PointerButton {
                    pos: triangle,
                    button: PointerButton::Primary,
                    pressed: true,
                    modifiers: Default::default(),
                },
                Event::PointerButton {
                    pos: triangle,
                    button: PointerButton::Primary,
                    pressed: false,
                    modifiers: Default::default(),
                },
            ],
        );
        assert_eq!(
            arr.session.playing[0],
            Some(last),
            "the scrolled slot launched"
        );
    }

    /// Dragging the seam on the mixer's top edge resizes the section,
    /// clamped to its range — and the rows' scroll bound follows the
    /// space that is left.
    #[test]
    fn the_mixer_seam_resizes_the_section() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        session_pass(&ctx, &mut arr, vec![]);
        assert_eq!(arr.session_mixer_h, SESSION_MIXER_H);

        let area = Rect::from_min_size(pos2(0.0, 0.0), SCREEN);
        let layout = SessionLayout::new(
            area,
            arr.tracks.len(),
            arr.session.scenes.len(),
            0.0,
            0.0,
            arr.session_mixer_h,
        );
        let seam = layout.mixer_seam().center();
        let up = pos2(seam.x, seam.y - 80.0);
        session_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(seam),
                Event::PointerButton {
                    pos: seam,
                    button: PointerButton::Primary,
                    pressed: true,
                    modifiers: Default::default(),
                },
            ],
        );
        session_pass(&ctx, &mut arr, vec![Event::PointerMoved(up)]);
        assert!(
            (arr.session_mixer_h - (SESSION_MIXER_H + 80.0)).abs() < 2.0,
            "the seam followed the hand: {}",
            arr.session_mixer_h
        );
        session_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(up),
                Event::PointerButton {
                    pos: up,
                    button: PointerButton::Primary,
                    pressed: false,
                    modifiers: Default::default(),
                },
            ],
        );

        // The clamp holds at both ends, wherever the pointer goes.
        arr.session_mixer_h = 9_999.0;
        session_pass(&ctx, &mut arr, vec![]);
        assert!(
            arr.session_mixer_h <= SCREEN.y * 0.5 + 1.0,
            "the mixer may take at most half the area: {}",
            arr.session_mixer_h
        );
        arr.session_mixer_h = 0.0;
        session_pass(&ctx, &mut arr, vec![]);
        assert_eq!(arr.session_mixer_h, *SESSION_MIXER_H_RANGE.start());
    }

    /// The fader's taper is linear in DECIBELS, which is what makes it feel
    /// even under the hand, and the bottom of the travel is silence rather
    /// than merely quiet.
    #[test]
    fn the_fader_is_linear_in_decibels() {
        // Unity sits where 0 dB falls on the travel.
        let unity = amp_to_fader(1.0);
        assert!((fader_to_amp(unity) - 1.0).abs() < 1e-4);
        assert!(
            (0.85..0.95).contains(&unity),
            "unity is near the top, where the resolution belongs: {unity}"
        );

        // Equal distances are equal dB, anywhere on the travel.
        let db_at = |p: f32| 20.0 * fader_to_amp(p).log10();
        let low = db_at(0.5) - db_at(0.4);
        let high = db_at(0.9) - db_at(0.8);
        assert!(
            (low - high).abs() < 0.01,
            "the same distance is the same dB: {low} vs {high}"
        );

        // The ends: silence at the bottom, +6 dB at the top.
        assert_eq!(fader_to_amp(0.0), 0.0, "a closed fader is off, not quiet");
        assert_eq!(amp_to_fader(0.0), 0.0);
        assert!((20.0 * fader_to_amp(1.0).log10() - FADER_MAX_DB).abs() < 0.01);
        // And the round trip holds across the range.
        for step in 0..=10 {
            let position = step as f32 / 10.0;
            let back = amp_to_fader(fader_to_amp(position));
            assert!((back - position).abs() < 1e-3, "round trip at {position}");
        }

        assert_eq!(volume_label(1.0), "+0.0");
        assert_eq!(volume_label(0.0), "-inf");
        assert_eq!(volume_label(0.5), "-6.0");
    }

    /// Dragging a strip's fader sets that track's volume and nobody
    /// else's, and double-clicking returns it to unity.
    #[test]
    fn the_strip_fader_sets_its_own_track_s_volume() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        session_pass(&ctx, &mut arr, vec![]);

        let layout = SessionLayout::new(
            Rect::from_min_size(pos2(0.0, 0.0), SCREEN),
            arr.tracks.len(),
            arr.session.scenes.len(),
            0.0,
            0.0,
            SESSION_MIXER_H,
        );
        // The assembly of track 1, from the same helper the strip lays
        // out with — the test and the paint cannot disagree about where
        // the fader is.
        let (_, travel, _) = strip_assembly(layout.mixer(1));
        let x = travel.center().x;
        let handle_h = 9.0f32.min(travel.height());
        let top = travel.top() + handle_h * 0.5;
        let bottom = travel.bottom() - handle_h * 0.5;

        // Press at unity, drag most of the way down.
        let press = pos2(x, top + (bottom - top) * (1.0 - amp_to_fader(1.0)));
        let to = pos2(x, bottom - 4.0);
        session_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(press),
                Event::PointerButton {
                    pos: press,
                    button: PointerButton::Primary,
                    pressed: true,
                    modifiers: Default::default(),
                },
            ],
        );
        session_pass(&ctx, &mut arr, vec![Event::PointerMoved(to)]);
        assert!(
            arr.tracks[1].volume < 0.5,
            "the fader pulled the level down: {}",
            arr.tracks[1].volume
        );
        assert_eq!(arr.tracks[0].volume, 1.0, "and nobody else's");
        session_pass(
            &ctx,
            &mut arr,
            vec![Event::PointerButton {
                pos: to,
                button: PointerButton::Primary,
                pressed: false,
                modifiers: Default::default(),
            }],
        );

        // Double-click returns it to unity.
        for _ in 0..2 {
            session_pass(
                &ctx,
                &mut arr,
                vec![
                    Event::PointerMoved(press),
                    Event::PointerButton {
                        pos: press,
                        button: PointerButton::Primary,
                        pressed: true,
                        modifiers: Default::default(),
                    },
                    Event::PointerButton {
                        pos: press,
                        button: PointerButton::Primary,
                        pressed: false,
                        modifiers: Default::default(),
                    },
                ],
            );
        }
        assert_eq!(arr.tracks[1].volume, 1.0, "double-click is back to unity");
    }

    /// A file dragged over the launcher aims at the slot under it — audio
    /// tracks only. This is the only way an audio clip reaches a slot, so
    /// without it half the grid would be unfillable.
    #[test]
    fn a_file_drag_aims_at_the_slot_under_it() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        let audio = arr.add_track(TrackKind::Audio);
        let mut drag = DragImport {
            path: "/tmp/kick.wav".into(),
            name: "kick".into(),
            header: Some((48_000, 48_000)),
            accepted: true,
            spot: None,
        };
        let drag_pass = |ctx: &egui::Context, arr: &mut Arrangement, drag: &mut DragImport, pos| {
            let mut out = ctx.run_ui(input(vec![Event::PointerMoved(pos)]), |ui| {
                let theme = Theme::dark();
                egui::CentralPanel::default()
                    .frame(egui::Frame::new().fill(theme.bg))
                    .show(ui, |ui| {
                        session_body(
                            ui,
                            &mut Focus::default(),
                            &theme,
                            arr,
                            4,
                            0.0,
                            &[],
                            Some(drag),
                        );
                    });
            });
            out.textures_delta.clear();
        };

        let layout = SessionLayout::new(
            Rect::from_min_size(pos2(0.0, 0.0), SCREEN),
            arr.tracks.len(),
            arr.session.scenes.len(),
            arr.session_scroll,
            0.0,
            SESSION_MIXER_H,
        );
        drag_pass(&ctx, &mut arr, &mut drag, layout.slot(audio, 3).center());
        assert_eq!(
            drag.spot,
            Some(DropSpot::Slot {
                track: audio,
                scene: 3
            })
        );

        // A MIDI column refuses: a slot there needs notes, not a file.
        drag_pass(&ctx, &mut arr, &mut drag, layout.slot(0, 3).center());
        assert_eq!(drag.spot, None);

        // And so does a file the importer would refuse.
        drag.accepted = false;
        drag_pass(&ctx, &mut arr, &mut drag, layout.slot(audio, 3).center());
        assert_eq!(drag.spot, None);
    }

    /// Tab flips the main area, and does not disturb Shift+Tab's meaning.
    #[test]
    fn tab_flips_the_main_area() {
        let ctx = egui::Context::default();
        let mut actions = Vec::new();
        let mut out = ctx.run_ui(
            input(vec![Event::Key {
                key: egui::Key::Tab,
                physical_key: None,
                pressed: true,
                repeat: false,
                modifiers: Default::default(),
            }]),
            |_ui| {},
        );
        out.textures_delta.clear();
        arrangement_keys(&ctx, &Arrangement::default(), &mut actions);
        assert_eq!(actions, vec![UiAction::ToggleMainView]);

        // And the verb itself flips, both ways.
        let mut arr = Arrangement::default();
        let mut transport = Transport::default();
        assert_eq!(arr.main_view, MainView::Timeline);
        perform(&actions, &mut transport, &mut arr);
        assert_eq!(arr.main_view, MainView::Session);
        perform(&actions, &mut transport, &mut arr);
        assert_eq!(arr.main_view, MainView::Timeline);
    }

    /// The grid's two halves: a slot's triangle launches it, and the rest
    /// of the slot selects it without starting anything. Run through the
    /// real widgets, from the real layout's rects.
    #[test]
    fn a_slot_launches_from_its_triangle_and_selects_from_its_body() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        assert!(arr.create_slot_clip(0, 1, 4.0));
        arr.session.selected = None;
        session_pass(&ctx, &mut arr, vec![]);

        let layout = SessionLayout::new(
            Rect::from_min_size(pos2(0.0, 0.0), SCREEN),
            arr.tracks.len(),
            arr.session.scenes.len(),
            arr.session_scroll,
            0.0,
            SESSION_MIXER_H,
        );
        let slot = layout.slot(0, 1);
        let click = |ctx: &egui::Context, arr: &mut Arrangement, pos: egui::Pos2| {
            session_pass(
                ctx,
                arr,
                vec![
                    Event::PointerMoved(pos),
                    Event::PointerButton {
                        pos,
                        button: PointerButton::Primary,
                        pressed: true,
                        modifiers: Default::default(),
                    },
                    Event::PointerButton {
                        pos,
                        button: PointerButton::Primary,
                        pressed: false,
                        modifiers: Default::default(),
                    },
                ],
            );
        };

        // The body: selects, launches nothing.
        click(&ctx, &mut arr, slot.center());
        assert_eq!(arr.session.selected, Some((0, 1)));
        assert_eq!(arr.session.playing[0], None, "the body does not launch");
        assert!(!arr.force_recompile);

        // The triangle: launches.
        let triangle = pos2(slot.left() + SLOT_LAUNCH_W * 0.5, slot.center().y);
        click(&ctx, &mut arr, triangle);
        assert_eq!(arr.session.playing[0], Some(1), "the triangle launched it");
        assert!(
            arr.force_recompile,
            "and asked for the swap on the press, not after the debounce"
        );

        // The stop button under the column hands the track back.
        arr.force_recompile = false;
        click(&ctx, &mut arr, layout.stop(0).center());
        assert_eq!(arr.session.playing[0], None);
        assert!(arr.force_recompile);
    }

    /// The scene column launches a whole row, and "+ scene" grows the grid
    /// without disturbing what is in it.
    #[test]
    fn the_scene_column_launches_a_row_and_grows_the_grid() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        assert!(arr.create_slot_clip(0, 0, 4.0));
        assert!(arr.create_slot_clip(2, 0, 4.0));
        session_pass(&ctx, &mut arr, vec![]);

        let layout = SessionLayout::new(
            Rect::from_min_size(pos2(0.0, 0.0), SCREEN),
            arr.tracks.len(),
            arr.session.scenes.len(),
            arr.session_scroll,
            0.0,
            SESSION_MIXER_H,
        );
        let click = |ctx: &egui::Context, arr: &mut Arrangement, pos: egui::Pos2| {
            session_pass(
                ctx,
                arr,
                vec![
                    Event::PointerMoved(pos),
                    Event::PointerButton {
                        pos,
                        button: PointerButton::Primary,
                        pressed: true,
                        modifiers: Default::default(),
                    },
                    Event::PointerButton {
                        pos,
                        button: PointerButton::Primary,
                        pressed: false,
                        modifiers: Default::default(),
                    },
                ],
            );
        };

        // The row's TRIANGLE launches; the rest of the row selects. Same
        // division as the slots.
        let scene0 = layout.scene(0);
        let triangle = pos2(scene0.left() + SLOT_LAUNCH_W * 0.5, scene0.center().y);
        click(&ctx, &mut arr, triangle);
        assert_eq!(arr.session.playing[0], Some(0));
        assert_eq!(arr.session.playing[2], Some(0));
        assert_eq!(arr.session.playing[1], None, "row 0 is empty on lane 1");
        assert_eq!(
            arr.session.selected_scene,
            Some(1),
            "launching selects the NEXT scene, ready for the next Enter"
        );
        click(&ctx, &mut arr, scene0.center());
        assert_eq!(
            arr.session.selected_scene,
            Some(0),
            "the name selects without launching"
        );

        let scenes = arr.session.scenes.len();
        click(&ctx, &mut arr, layout.add_scene().center());
        assert_eq!(arr.session.scenes.len(), scenes + 1);
        assert!(
            arr.session.slots.iter().all(|c| c.len() == scenes + 1),
            "every column grew a row"
        );
        assert!(arr.session.slot(0, 0).is_some(), "and kept what it had");

        click(&ctx, &mut arr, layout.stop_all().center());
        assert!(arr.session.playing.iter().all(Option::is_none));
    }

    /// Launching is per track: a launched clip overrides that track's
    /// timeline and nothing else's, and stopping hands the track straight
    /// back to it. An empty slot stops rather than launching, which is what
    /// makes a scene launch across a row with holes do the obvious thing.
    #[test]
    fn a_launched_slot_overrides_only_its_own_track() {
        let mut arr = Arrangement::default();
        // Timeline content on lanes 0 and 1, a session clip on lane 0.
        arr.create_clip(0, 12.0, 4.0).unwrap();
        arr.create_clip(1, 20.0, 4.0).unwrap();
        assert!(arr.create_slot_clip(0, 2, 4.0));

        // Nothing launched: the timeline plays, untouched.
        let idle = arr.effective_clips();
        assert_eq!(idle[0].len(), 1);
        assert_eq!(idle[0][0].start, 12.0);

        assert!(arr.session.launch(0, 2));
        let playing = arr.effective_clips();
        // ONE clip carrying a brace, rather than one copy per repeat.
        // The repeats used to be spelled out as clips; they are now the
        // clip's own internal loop, which is the same sound and the same
        // rule the timeline uses.
        assert_eq!(playing[0].len(), 1, "the launcher built copies again");
        assert_eq!(playing[0][0].start, 0.0, "it plays from the launch, not 12");
        assert_eq!(
            clip_loop(&playing[0][0]),
            Some((0.0, 4.0)),
            "it repeats a clip-length later"
        );
        assert!(
            playing[0][0].start + playing[0][0].len >= SESSION_HORIZON_BEATS,
            "the repeats reach the horizon"
        );
        assert_eq!(
            playing[1], idle[1],
            "the other track still plays its timeline"
        );

        // Stopping hands the track back.
        assert!(arr.session.stop_track(0));
        assert_eq!(arr.effective_clips(), idle);

        // An empty slot stops instead of launching.
        assert!(arr.session.launch(0, 2));
        assert!(arr.session.launch(0, 5), "an empty slot is a stop");
        assert_eq!(arr.session.playing[0], None);
        assert_eq!(arr.effective_clips(), idle);
    }

    #[test]
    fn session_launches_are_placed_on_the_requested_quantized_edge() {
        let mut arr = Arrangement::default();
        assert!(arr.create_slot_clip(0, 0, 4.0));
        assert!(arr.session.launch_at(0, 0, 12.0));
        let clips = arr.effective_clips();
        // One clip from the launch edge, repeating every clip length —
        // the repeats are the clip's own brace now, not a row of copies.
        assert_eq!(clips[0][0].start, 12.0);
        assert_eq!(clip_loop(&clips[0][0]), Some((0.0, 4.0)));

        assert_eq!(LaunchQuantization::Bar.launch_beat(10.25, 4), 12.0);
        assert_eq!(LaunchQuantization::Beat.launch_beat(10.25, 4), 11.0);
        assert_eq!(LaunchQuantization::Off.launch_beat(10.25, 4), 10.25);
    }

    #[test]
    fn track_automation_holds_then_interpolates_between_points() {
        let mut automation = TrackAutomation::default();
        automation.insert(TRACK_VOLUME_TARGET, 4.0, 0.25);
        automation.insert(TRACK_VOLUME_TARGET, 8.0, 1.25);
        assert_eq!(automation.value_at(TRACK_VOLUME_TARGET, 2.0, 1.0), 1.0);
        assert_eq!(automation.value_at(TRACK_VOLUME_TARGET, 4.0, 1.0), 0.25);
        assert_eq!(automation.value_at(TRACK_VOLUME_TARGET, 6.0, 1.0), 0.75);
        assert_eq!(automation.value_at(TRACK_VOLUME_TARGET, 12.0, 1.0), 1.25);
    }

    #[test]
    fn automation_points_shape_their_outgoing_segment() {
        let mut automation = TrackAutomation::default();
        automation.insert(TRACK_PAN_TARGET, 0.0, -1.0);
        automation.insert(TRACK_PAN_TARGET, 4.0, 1.0);
        automation.points_mut(TRACK_PAN_TARGET)[0].bend = 0.5;
        assert!(
            automation.value_at(TRACK_PAN_TARGET, 2.0, 0.0) < -0.45,
            "a positive bend should stay close to its source at the midpoint"
        );
        automation.points_mut(TRACK_PAN_TARGET)[0].bend = -0.5;
        assert!(
            automation.value_at(TRACK_PAN_TARGET, 2.0, 0.0) > 0.45,
            "a negative bend should bow above the line"
        );
    }

    /// An audio slot loops INSIDE one node rather than being repeated: a
    /// repeat per bar would be one disk stream per bar.
    #[test]
    fn a_launched_audio_slot_loops_in_one_node() {
        let mut arr = Arrangement::default();
        let track = arr.add_track(TrackKind::Audio);
        arr.session.slots[track][0] = Some(Clip {
            id: 1,
            name: "loop".into(),
            start: 0.0,
            len: 4.0,
            notes: Vec::new(),
            audio: Some(AudioSource {
                transpose: 0.0,
                detune: 0.0,
                transposed_from: None,
                applied_ratio: 1.0,
                path: "/tmp/loop.wav".into(),
                sample_rate: 48_000,
                source_offset: 0,
                source_frames: 96_000,
                gain: 1.0,
                looped: false,
                file_frames: 0,
                reversed: false,
                fade_in: 0,
                fade_out: 0,
                fade_in_curve: 0.0,
                fade_out_curve: 0.0,
                envelope: Vec::new(),
            }),
            ..Clip::default()
        });
        assert!(arr.session.launch(track, 0));

        let playing = arr.effective_clips();
        assert_eq!(playing[track].len(), 1, "one node, not one per repeat");
        assert_eq!(playing[track][0].len, SESSION_HORIZON_BEATS);
        assert!(
            playing[track][0].audio.as_ref().is_some_and(|a| a.looped),
            "it loops rather than playing once and stopping"
        );
    }

    /// A scene is the state of every track, not only of the ones it fills.
    #[test]
    fn launching_a_scene_stops_the_tracks_it_does_not_fill() {
        let mut arr = Arrangement::default();
        assert!(arr.create_slot_clip(0, 0, 4.0));
        assert!(arr.create_slot_clip(1, 1, 4.0));

        arr.session.launch_scene(0);
        assert_eq!(arr.session.playing[0], Some(0));
        assert_eq!(arr.session.playing[1], None, "lane 1 has nothing in row 0");

        arr.session.launch_scene(1);
        assert_eq!(arr.session.playing[0], None, "lane 0 has nothing in row 1");
        assert_eq!(arr.session.playing[1], Some(1));

        arr.session.launch_scene(0);
        assert!(arr.session.stop_all());
        assert!(arr.session.playing.iter().all(Option::is_none));
    }

    /// Emptying a slot that is playing stops it: a track left "playing"
    /// something that is no longer there would be a lie the transport
    /// keeps telling.
    #[test]
    fn clearing_a_playing_slot_stops_the_track() {
        let mut arr = Arrangement::default();
        assert!(arr.create_slot_clip(2, 3, 4.0));
        assert!(arr.session.launch(2, 3));
        assert_eq!(arr.session.selected, Some((2, 3)));

        assert!(arr.clear_slot(2, 3));
        assert_eq!(arr.session.playing[2], None);
        assert_eq!(arr.session.selected, None);
        assert!(!arr.clear_slot(2, 3), "a second clear is a clean no-op");

        // Audio tracks refuse an empty clip: a slot there needs a file.
        let audio = arr.add_track(TrackKind::Audio);
        assert!(!arr.create_slot_clip(audio, 0, 4.0));
    }

    /// The grid is parallel to the tracks, exactly like the clips: every
    /// track operation maintains all of them or the columns misaddress.
    #[test]
    fn the_session_grid_follows_its_tracks() {
        let mut arr = Arrangement::default();
        assert!(arr.create_slot_clip(0, 0, 4.0));
        let id = arr.session.slot(0, 0).unwrap().id;
        assert!(arr.session.launch(0, 0));

        // A new track brings a column with it.
        let added = arr.add_track(TrackKind::Midi);
        assert_eq!(arr.session.slots.len(), arr.tracks.len());
        assert_eq!(arr.session.playing.len(), arr.tracks.len());
        assert!(arr.session.slots[added].iter().all(Option::is_none));

        // A reorder carries the column AND what it is playing.
        assert!(arr.move_track(0, 2));
        assert_eq!(arr.session.slot(2, 0).map(|c| c.id), Some(id));
        assert_eq!(arr.session.playing[2], Some(0), "still playing, new index");
        assert!(arr.session.slot(0, 0).is_none());

        // And a removal takes the column with it.
        assert!(arr.remove_track(2));
        assert_eq!(arr.session.slots.len(), arr.tracks.len());
        assert_eq!(arr.session.playing.len(), arr.tracks.len());
        assert!(
            arr.session.slots.iter().flatten().all(Option::is_none),
            "the only slot clip went with its track"
        );
    }

    /// Slots are content, so they undo. What is PLAYING is not — but it
    /// must still be made to fit a grid the undo changed under it.
    #[test]
    fn undo_reaches_the_session_grid() {
        let mut arr = Arrangement::default();
        let mut history = History::new(&arr);
        assert!(arr.create_slot_clip(1, 2, 4.0));
        history.sync(&arr, true);
        assert!(arr.session.launch(1, 2));

        assert!(history.undo(&mut arr));
        assert!(arr.session.slot(1, 2).is_none(), "the slot is empty again");
        assert_eq!(
            arr.session.playing[1], None,
            "and the track is not left playing what is no longer there"
        );

        assert!(history.redo(&mut arr));
        assert!(arr.session.slot(1, 2).is_some(), "redo brings it back");
    }

    /// A reorder carries the lane's clips with it, shifts everything
    /// between the two ends by one, and keeps every mark pointing at the
    /// lane the user meant rather than at the index it used to occupy.
    #[test]
    fn moving_a_track_carries_its_clips_and_its_marks() {
        let mut arr = Arrangement::default();
        // One clip per lane, named for the lane it started on.
        for t in 0..4 {
            arr.create_clip(t, t as f32 * 8.0, 4.0).unwrap();
        }
        let ids: Vec<u64> = (0..4).map(|t| arr.clips[t][0].id).collect();

        // Downwards: lane 0 to the end. 1, 2 and 3 each shift up one.
        arr.select_track(0);
        arr.selected_clip = Some((0, 0));
        arr.cursor = Some((2, 4.0));
        assert!(arr.move_track(0, 3));
        assert_eq!(arr.clips[3][0].id, ids[0], "the clips came along");
        assert_eq!(arr.clips[0][0].id, ids[1]);
        assert_eq!(arr.selected, Some(3), "the selection followed its lane");
        assert_eq!(arr.selected_clip, Some((3, 0)));
        assert_eq!(arr.cursor, Some((1, 4.0)), "a lane between shifted up");
        assert!(arr.force_recompile, "the app is told the indices moved");

        // And back up: the arrangement returns to where it started.
        assert!(arr.move_track(3, 0));
        let back: Vec<u64> = (0..4).map(|t| arr.clips[t][0].id).collect();
        assert_eq!(back, ids, "a move and its reverse cancel out");
        assert_eq!(arr.selected, Some(0));
        assert_eq!(arr.cursor, Some((2, 4.0)));

        // Nothing to do is not a move: the flag stays where it was.
        arr.force_recompile = false;
        assert!(!arr.move_track(1, 1));
        assert!(
            !arr.move_track(9, 0),
            "out of range is refused, not clamped"
        );
        assert!(!arr.force_recompile);
    }

    /// The palette's route: nudging clamps at the ends instead of wrapping
    /// or refusing to move at all.
    #[test]
    fn nudging_a_track_clamps_at_the_ends() {
        let mut arr = Arrangement {
            selected: Some(0),
            ..Default::default()
        };
        assert!(!arr.nudge_track(-1), "the top lane cannot go higher");
        assert!(arr.nudge_track(1));
        assert_eq!(arr.selected, Some(1));

        let last = arr.tracks.len() - 1;
        arr.select_track(last);
        assert!(!arr.nudge_track(1), "the bottom lane cannot go lower");
        assert!(arr.nudge_track(-1));
        assert_eq!(arr.selected, Some(last - 1));
    }

    /// Dragging a header past the lane below it reorders the stack on
    /// release — through the real header widgets, and as one undo step.
    #[test]
    fn dragging_a_header_reorders_the_stack() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        arr.create_clip(0, 0.0, 4.0).unwrap();
        let moved = arr.tracks[0].name.clone();
        let displaced = arr.tracks[1].name.clone();
        arrangement_pass(&ctx, &mut arr, vec![]);
        let mut history = History::new(&arr);

        // Press on lane 0's header — x inside the column, left of TL — and
        // pull down past the middle of lane 1.
        let press = pos2(HEADER_W * 0.5, LANES_TOP + TRACK_H * 0.5);
        let over = pos2(HEADER_W * 0.5, LANES_TOP + TRACK_H * 1.6);
        arrangement_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(press),
                Event::PointerButton {
                    pos: press,
                    button: PointerButton::Primary,
                    pressed: true,
                    modifiers: Default::default(),
                },
            ],
        );
        arrangement_pass(&ctx, &mut arr, vec![Event::PointerMoved(over)]);
        assert!(arr.track_drag.is_some(), "the drag is in flight");
        assert_eq!(arr.tracks[0].name, moved, "nothing moves until the release");

        arrangement_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(over),
                Event::PointerButton {
                    pos: over,
                    button: PointerButton::Primary,
                    pressed: false,
                    modifiers: Default::default(),
                },
            ],
        );
        assert!(arr.track_drag.is_none(), "the drag is done");
        assert_eq!(arr.tracks[0].name, displaced, "lane 1 came up");
        assert_eq!(arr.tracks[1].name, moved, "the carried lane landed below");
        assert_eq!(arr.clips[1].len(), 1, "its clip came with it");
        assert!(arr.clips[0].is_empty());

        // And the whole drag is one step of history.
        arrangement_pass(&ctx, &mut arr, vec![]);
        history.sync(&arr, true);
        assert_eq!(history.past.len(), 1);
        assert!(history.undo(&mut arr));
        assert_eq!(arr.tracks[0].name, moved, "undo puts the stack back");
        assert_eq!(arr.clips[0].len(), 1);
    }

    /// The header's controls are created AFTER the draggable body, so they
    /// win the pointer where they overlap it. Without that ordering the
    /// reorder drag would swallow mute, solo, pan and rename — every
    /// control on the header — so this pins it.
    #[test]
    fn the_header_controls_still_win_the_pointer() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        arrangement_pass(&ctx, &mut arr, vec![]);

        // The mute button of lane 0, from the same metrics the header
        // lays it out with.
        let row_y = LANES_TOP + HEADER_PAD + HEADER_NAME_H;
        let mute = pos2(HEADER_PAD + HEADER_BTN * 0.5, row_y + HEADER_BTN * 0.5);
        let click = |ctx: &egui::Context, arr: &mut Arrangement, pos: egui::Pos2| {
            arrangement_pass(
                ctx,
                arr,
                vec![
                    Event::PointerMoved(pos),
                    Event::PointerButton {
                        pos,
                        button: PointerButton::Primary,
                        pressed: true,
                        modifiers: Default::default(),
                    },
                    Event::PointerButton {
                        pos,
                        button: PointerButton::Primary,
                        pressed: false,
                        modifiers: Default::default(),
                    },
                ],
            );
        };

        click(&ctx, &mut arr, mute);
        assert!(arr.tracks[0].mute, "the mute button took the click");
        assert!(!arr.tracks[0].solo, "mute changed only mute");
        assert!(arr.track_drag.is_none(), "and no reorder drag began");

        // The solo button sits one slot to its right.
        let solo = pos2(mute.x + HEADER_BTN + HEADER_CONTROL_GAP, mute.y);
        click(&ctx, &mut arr, solo);
        assert!(arr.tracks[0].solo, "the solo button took its click too");
        assert!(
            arr.tracks[0].mute,
            "solo did not clear or otherwise mutate mute"
        );

        // And the stack never moved through any of it.
        assert_eq!(arr.tracks.len(), TRACK_COUNT);
        assert!(!arr.force_recompile);
    }

    /// One pure layout owns both paint and hit testing. It must degrade as a
    /// unit: at the threshold every control exists and immediately below it
    /// none does, while identity and activity keep their permanent address.
    #[test]
    fn track_header_layout_is_stable_and_degrades_as_one_unit() {
        let normal =
            track_header_layout(Rect::from_min_size(pos2(0.0, 0.0), vec2(HEADER_W, TRACK_H)));
        let controls = normal.controls.expect("default height has controls");
        assert!(normal.name.right() <= normal.kind.left());
        assert!(normal.kind.right() <= normal.meter.left());
        assert!(controls.mute.right() <= controls.solo.left());
        assert!(controls.solo.right() <= controls.pan_value.left());
        assert!(controls.pan_value.right() <= controls.pan.left());
        assert!(controls.pan.right() <= normal.meter.left());

        let at = track_header_layout(Rect::from_min_size(
            pos2(0.0, 0.0),
            vec2(HEADER_W, HEADER_ROWS_MIN_H),
        ));
        assert!(at.controls.is_some(), "the threshold is inclusive");
        let below = track_header_layout(Rect::from_min_size(
            pos2(0.0, 0.0),
            vec2(HEADER_W, HEADER_ROWS_MIN_H - 0.01),
        ));
        assert!(below.controls.is_none(), "the whole row disappears");
        assert!(below.identity.is_positive());
        assert!(below.meter.is_positive());
    }

    /// Double-click is the hardware-panel route back to the pan detent. It
    /// must land on exact floating-point zero, not merely draw a centred
    /// needle over a residual value.
    #[test]
    fn header_pan_double_click_returns_to_exact_center() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        arr.tracks[0].pan = 0.73;
        arrangement_pass(&ctx, &mut arr, vec![]);
        let head = Rect::from_min_size(pos2(0.0, LANES_TOP), vec2(HEADER_W, TRACK_H));
        let pan = track_header_layout(head)
            .controls
            .expect("default controls")
            .pan
            .center();
        for _ in 0..2 {
            arrangement_pass(
                &ctx,
                &mut arr,
                vec![
                    Event::PointerMoved(pan),
                    Event::PointerButton {
                        pos: pan,
                        button: PointerButton::Primary,
                        pressed: true,
                        modifiers: Default::default(),
                    },
                    Event::PointerButton {
                        pos: pan,
                        button: PointerButton::Primary,
                        pressed: false,
                        modifiers: Default::default(),
                    },
                ],
            );
        }
        assert_eq!(arr.tracks[0].pan, 0.0);
        assert_eq!(
            arr.selected,
            Some(0),
            "the control also activates its track"
        );
        assert!(arr.track_drag.is_none());
    }

    /// Escape cancels the entire gesture, not just one frame of it. Pointer
    /// motion after the cancel remains inert until release.
    #[test]
    fn header_pan_escape_restores_and_cancels_the_drag() {
        let ctx = egui::Context::default();
        let mut arr = Arrangement::default();
        arr.tracks[0].pan = 0.25;
        arrangement_pass(&ctx, &mut arr, vec![]);
        let center = track_header_layout(Rect::from_min_size(
            pos2(0.0, LANES_TOP),
            vec2(HEADER_W, TRACK_H),
        ))
        .controls
        .expect("default controls")
        .pan
        .center();
        let moved = center - vec2(0.0, 18.0);
        arrangement_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(center),
                Event::PointerButton {
                    pos: center,
                    button: PointerButton::Primary,
                    pressed: true,
                    modifiers: Default::default(),
                },
            ],
        );
        arrangement_pass(&ctx, &mut arr, vec![Event::PointerMoved(moved)]);
        assert_ne!(arr.tracks[0].pan, 0.25, "the drag first moved the value");

        arrangement_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(moved),
                Event::Key {
                    key: egui::Key::Escape,
                    physical_key: None,
                    pressed: true,
                    repeat: false,
                    modifiers: Default::default(),
                },
            ],
        );
        assert_eq!(arr.tracks[0].pan, 0.25, "Escape restored the origin");

        let farther = center - vec2(0.0, 30.0);
        arrangement_pass(&ctx, &mut arr, vec![Event::PointerMoved(farther)]);
        assert_eq!(
            arr.tracks[0].pan, 0.25,
            "the cancelled gesture stayed inert before release"
        );
        arrangement_pass(
            &ctx,
            &mut arr,
            vec![
                Event::PointerMoved(farther),
                Event::PointerButton {
                    pos: farther,
                    button: PointerButton::Primary,
                    pressed: false,
                    modifiers: Default::default(),
                },
            ],
        );
        assert_eq!(arr.tracks[0].pan, 0.25);
    }

    /// The header rail reads the Session mixer's existing ballistics, and a
